const i=[{slug:"offer",title:"Публичная оферта",subtitle:"Договор о предоставлении доступа к сервису НЭК CRM",version:"14 августа 2026 года",blocks:[{k:"h",t:"ПУБЛИЧНАЯ ОФЕРТА"},{k:"h",t:"на заключение договора о предоставлении доступа к сервису НЭК CRM"},{k:"h",t:"Редакция от 14 августа 2026 года"},{k:"p",t:"Настоящий документ является официальным предложением индивидуального предпринимателя Неклюдова Артема Анатольевича, ИНН 263221164126, ОГРНИП 324265100105224 (далее — Исполнитель), заключить договор о предоставлении доступа к сервису НЭК CRM на изложенных ниже условиях."},{k:"p",t:"Оферта адресована юридическим лицам, индивидуальным предпринимателям, плательщикам налога на профессиональный доход и иным лицам, правомерно использующим Сервис в целях осуществления предпринимательской или профессиональной деятельности."},{k:"p",t:"Сервис не предназначен для использования исключительно в личных, семейных, домашних и иных целях, не связанных с предпринимательской или профессиональной деятельностью."},{k:"p",t:"Акцепт настоящей Оферты означает полное и безоговорочное принятие ее условий."},{k:"h",t:"1. Термины и определения"},{k:"p",t:"1.1. НЭК CRM / Сервис — программный сервис, доступный посредством сети Интернет и предназначенный для автоматизации деятельности сервисных центров, ремонтных организаций, мастеров и иных Пользователей, включая учет клиентов, устройств, заказов, ремонтов, работ, комплектующих, платежей, документов, сотрудников и иных связанных с деятельностью Пользователя сведений."},{k:"p",t:"1.2. Сайт — сайт Исполнителя по адресу https://nakcrm.ru, включая его страницы и поддомены."},{k:"p",t:"1.3. Исполнитель — индивидуальный предприниматель Неклюдов Артем Анатольевич."},{k:"p",t:"1.4. Заказчик — юридическое лицо, индивидуальный предприниматель, плательщик налога на профессиональный доход или иное лицо, которое акцептовало настоящую Оферту и использует НЭК CRM в связи со своей предпринимательской или профессиональной деятельностью."},{k:"p",t:"1.5. Пользователь — физическое лицо, непосредственно использующее НЭК CRM от своего имени либо от имени или по поручению Заказчика."},{k:"p",t:"1.6. Администратор — Пользователь, которому предоставлены полномочия по управлению организацией в НЭК CRM, в том числе созданию учетных записей, назначению ролей и прав доступа."},{k:"p",t:"1.7. Учетная запись / Аккаунт — совокупность данных и технических средств, позволяющих идентифицировать Пользователя и предоставлять ему доступ к НЭК CRM."},{k:"p",t:"1.8. Организация — созданное в НЭК CRM рабочее пространство Заказчика, в рамках которого осуществляется работа его сервисного центра, филиала, работников или иных Пользователей."},{k:"p",t:"1.9. Тариф — совокупность условий использования НЭК CRM, включая стоимость, расчетный период, доступную функциональность, лимиты, количество Пользователей, заказов или иные показатели."},{k:"p",t:"1.10. Расчетный период — период, за который определяется плата за использование Сервиса."},{k:"p",t:"1.11. Контент Заказчика — сведения, документы, изображения, файлы, клиентские базы, записи о заказах, устройствах и иная информация, размещаемая Заказчиком и его Пользователями в НЭК CRM."},{k:"p",t:"1.12. Клиентские данные — персональные данные клиентов, работников, представителей, контрагентов и иных физических лиц, которые Заказчик размещает в НЭК CRM."},{k:"p",t:"1.13. Поручение на обработку персональных данных — приложение к настоящей Оферте, определяющее условия обработки Исполнителем Клиентских данных по поручению Заказчика."},{k:"p",t:"1.14. Личный кабинет — часть интерфейса НЭК CRM, доступная Пользователю после прохождения авторизации."},{k:"p",t:"1.15. Простая электронная подпись / ПЭП — электронная подпись, формируемая с использованием данных авторизации Пользователя в порядке, предусмотренном настоящей Офертой."},{k:"h",t:"2. Предмет Договора"},{k:"p",t:"2.1. Исполнитель обязуется на условиях настоящей Оферты предоставить Заказчику удаленный доступ через сеть Интернет к функциональным возможностям НЭК CRM, а Заказчик обязуется соблюдать условия использования Сервиса и оплачивать его использование в случаях, предусмотренных выбранным Тарифом."},{k:"p",t:"2.2. В части программного обеспечения Исполнитель предоставляет Заказчику на срок действия оплаченного или иным образом предоставленного доступа простое (неисключительное), непередаваемое третьим лицам право использования НЭК CRM способами, прямо предусмотренными настоящим Договором."},{k:"p",t:"2.3. Право использования предоставляется исключительно путем удаленного доступа к Сервису через сеть Интернет без передачи Заказчику исходного кода и экземпляра программного обеспечения для самостоятельного размещения, если иное не предусмотрено отдельным письменным соглашением."},{k:"p",t:"2.4. В состав предоставления Сервиса могут также входить:"},{k:"li",t:"размещение и хранение данных;"},{k:"li",t:"техническое сопровождение;"},{k:"li",t:"обновление программного обеспечения;"},{k:"li",t:"создание резервных копий;"},{k:"li",t:"техническая поддержка;"},{k:"li",t:"предоставление интеграций;"},{k:"li",t:"формирование документов;"},{k:"li",t:"иные функции, предусмотренные соответствующим Тарифом."},{k:"p",t:"2.5. Настоящий Договор является смешанным и регулирует предоставление права использования программного обеспечения, удаленного доступа к нему и связанных с этим услуг."},{k:"p",t:"2.6. Исполнитель подтверждает наличие прав и полномочий в объеме, необходимом для законного предоставления Заказчикам права использования НЭК CRM."},{k:"h",t:"3. Порядок заключения Договора и акцепт Оферты"},{k:"p",t:"3.1. Настоящая Оферта является предложением заключить Договор на указанных в ней условиях."},{k:"p",t:"3.2. До акцепта Оферты Пользователю предоставляется возможность ознакомиться с ее актуальной редакцией."},{k:"p",t:"3.3. Акцепт осуществляется путем совершения Пользователем совокупности действий:"},{k:"li",t:"ознакомления с настоящей Офертой;"},{k:"li",t:"установки соответствующего флажка (чекбокса) о принятии Оферты;"},{k:"li",t:"нажатия кнопки регистрации, создания аккаунта, продолжения работы или иного элемента интерфейса, однозначно подтверждающего принятие условий."},{k:"p",t:"Если использование определенного Тарифа требует оплаты, совершение оплаты также подтверждает акцепт соответствующих условий Тарифа."},{k:"p",t:"3.4. Договор считается заключенным с момента регистрации учетной записи после акцепта Оферты либо с момента оплаты, если оплата была совершена ранее, в зависимости от того, какое событие наступило первым."},{k:"p",t:"3.5. Если Пользователь акцептует Оферту от имени юридического лица, индивидуального предпринимателя или иного Заказчика, он подтверждает наличие необходимых полномочий."},{k:"p",t:"3.6. Если учетная запись создается работником или иным лицом по приглашению уже существующего Заказчика, стороной Договора остается соответствующий Заказчик."},{k:"p",t:"3.7. Акцепт Оферты не является согласием физического лица на обработку его персональных данных в случаях, когда законодательством требуется отдельное согласие."},{k:"p",t:"Такое согласие оформляется отдельно."},{k:"h",t:"4. Регистрация и учетная запись"},{k:"p",t:"4.1. Для использования НЭК CRM Пользователь проходит процедуру регистрации и предоставляет сведения, предусмотренные интерфейсом Сервиса."},{k:"p",t:"4.2. Пользователь обязан предоставлять достоверную и актуальную информацию."},{k:"p",t:"4.3. Заказчик самостоятельно определяет:"},{k:"li",t:"перечень своих Пользователей;"},{k:"li",t:"их роли;"},{k:"li",t:"объем предоставляемого доступа;"},{k:"li",t:"право просмотра и изменения данных;"},{k:"li",t:"полномочия Администраторов."},{k:"p",t:"4.4. Действия Пользователей, которым Заказчик предоставил доступ к своей Организации, считаются действиями Заказчика в пределах предоставленных им полномочий."},{k:"p",t:"4.5. Заказчик обязан своевременно прекращать доступ работников и иных лиц, утративших соответствующие полномочия."},{k:"h",t:"5. Безопасность учетной записи"},{k:"p",t:"5.1. Пользователь обязан обеспечивать конфиденциальность пароля, одноразовых кодов и иных средств доступа к учетной записи."},{k:"p",t:"5.2. Запрещается:"},{k:"li",t:"передавать персональные данные авторизации посторонним лицам;"},{k:"li",t:"использовать одну персональную учетную запись несколькими лицами, если это не предусмотрено функциональностью Тарифа;"},{k:"li",t:"предоставлять доступ лицам, не имеющим соответствующих полномочий."},{k:"p",t:"5.3. При подозрении на компрометацию учетной записи Пользователь обязан изменить пароль и уведомить Исполнителя."},{k:"p",t:"5.4. До получения такого уведомления действия, совершенные после успешной авторизации с использованием учетных данных Пользователя, предполагаются совершенными соответствующим Пользователем, если Исполнитель не знал и не должен был знать об их неправомерности."},{k:"p",t:"5.5. Исполнитель вправе временно ограничить доступ к учетной записи при наличии объективных признаков ее компрометации."},{k:"h",t:"6. Простая электронная подпись"},{k:"p",t:"6.1. Стороны признают возможность использования простой электронной подписи при взаимодействии через НЭК CRM."},{k:"p",t:"6.2. Ключом простой электронной подписи признается совокупность используемых системой средств идентификации и аутентификации Пользователя, в том числе:"},{k:"li",t:"адрес электронной почты или номер телефона;"},{k:"li",t:"пароль;"},{k:"li",t:"одноразовый код подтверждения;"},{k:"li",t:"иной предусмотренный Сервисом идентификатор,"},{k:"p",t:"в зависимости от используемого способа авторизации."},{k:"p",t:"6.3. Электронный документ, заявление, команда, запрос или иное действие считается совершенным Пользователем с использованием ПЭП, если оно выполнено после успешной авторизации в его учетной записи."},{k:"p",t:"6.4. Для определения лица, совершившего действие, Исполнитель вправе использовать:"},{k:"li",t:"идентификатор учетной записи;"},{k:"li",t:"дату и время действия;"},{k:"li",t:"сведения о сессии;"},{k:"li",t:"IP-адрес;"},{k:"li",t:"системные журналы;"},{k:"li",t:"сведения о прохождении авторизации;"},{k:"li",t:"иные технические сведения."},{k:"p",t:"6.5. Пользователь обязан соблюдать конфиденциальность ключей ПЭП и незамедлительно уведомлять Исполнителя об их компрометации."},{k:"p",t:"6.6. Документы и действия, подписанные ПЭП в соответствии с настоящим разделом, признаются Сторонами равнозначными документам и волеизъявлениям, совершенным в простой письменной форме, в случаях, когда законодательством не требуется использование иного вида электронной подписи."},{k:"h",t:"7. Право использования НЭК CRM"},{k:"p",t:"7.1. На срок действия доступа Заказчику предоставляется простая неисключительная лицензия на использование НЭК CRM посредством удаленного доступа."},{k:"p",t:"7.2. Заказчик вправе:"},{k:"li",t:"использовать интерфейс НЭК CRM в своей деятельности;"},{k:"li",t:"создавать предусмотренное Тарифом количество учетных записей;"},{k:"li",t:"вносить и обрабатывать информацию;"},{k:"li",t:"формировать предусмотренные Сервисом документы;"},{k:"li",t:"использовать доступные интеграции;"},{k:"li",t:"экспортировать данные в предусмотренных функциональностью форматах;"},{k:"li",t:"пользоваться иными функциями соответствующего Тарифа."},{k:"p",t:"7.3. Территория использования права не ограничивается при условии соблюдения законодательства Российской Федерации и законодательства места фактического использования Сервиса."},{k:"p",t:"7.4. Исключительные права на программный код, структуру, дизайн, базы программных компонентов, элементы интерфейса, документацию и иные охраняемые элементы НЭК CRM Заказчику не передаются."},{k:"h",t:"8. Ограничения использования"},{k:"p",t:"8.1. Без письменного разрешения Исполнителя Заказчик не вправе:"},{k:"li",t:"копировать программный код НЭК CRM;"},{k:"li",t:"декомпилировать, дизассемблировать или иным способом пытаться получить исходный код, кроме прямо допускаемых законом случаев;"},{k:"li",t:"создавать производные программные продукты на основе НЭК CRM;"},{k:"li",t:"обходить технические ограничения;"},{k:"li",t:"вмешиваться в работу Сервиса;"},{k:"li",t:"осуществлять несанкционированное тестирование инфраструктуры на проникновение;"},{k:"li",t:"использовать автоматизированные средства массового получения информации в нарушение установленных лимитов;"},{k:"li",t:"передавать или перепродавать доступ к НЭК CRM вне своей организации;"},{k:"li",t:"предоставлять доступ конкурентному сервису с целью систематического копирования интерфейса, структуры или функциональности;"},{k:"li",t:"удалять обозначения об авторских и иных правах;"},{k:"li",t:"использовать Сервис для нарушения законодательства или прав третьих лиц."},{k:"p",t:"8.2. Ограничения настоящего раздела не препятствуют Заказчику самостоятельно выгружать и использовать принадлежащие ему данные."},{k:"h",t:"9. Функциональность Сервиса"},{k:"p",t:"9.1. Конкретный состав функций зависит от выбранного Тарифа."},{k:"p",t:"9.2. Описание функций, лимитов и стоимости Тарифов размещается на Сайте и (или) в интерфейсе НЭК CRM."},{k:"p",t:"9.3. Исполнитель вправе развивать Сервис, в том числе:"},{k:"li",t:"добавлять функции;"},{k:"li",t:"изменять интерфейс;"},{k:"li",t:"оптимизировать алгоритмы;"},{k:"li",t:"заменять технические компоненты;"},{k:"li",t:"прекращать поддержку устаревших функций."},{k:"p",t:"9.4. Изменения, не ухудшающие существенно оплаченные возможности Заказчика, могут вноситься без предварительного согласования."},{k:"p",t:"9.5. При планируемом существенном прекращении оплаченной функциональности Исполнитель по возможности уведомляет Заказчика заблаговременно."},{k:"p",t:"9.6. Изменения, необходимые для устранения уязвимости, исполнения требований закона или предотвращения угроз безопасности, могут применяться незамедлительно."},{k:"h",t:"10. Тарифы"},{k:"p",t:"10.1. Стоимость использования НЭК CRM определяется выбранным Тарифом."},{k:"p",t:"10.2. Тариф может предусматривать:"},{k:"li",t:"фиксированную абонентскую плату;"},{k:"li",t:"оплату за определенный период;"},{k:"li",t:"оплату исходя из количества Пользователей;"},{k:"li",t:"оплату исходя из количества заказов или операций;"},{k:"li",t:"переменную плату в зависимости от показателей использования Сервиса;"},{k:"li",t:"сочетание указанных способов."},{k:"p",t:"10.3. Тариф может устанавливать ограничения по:"},{k:"li",t:"числу сотрудников;"},{k:"li",t:"филиалам;"},{k:"li",t:"заказам;"},{k:"li",t:"объему хранилища;"},{k:"li",t:"интеграциям;"},{k:"li",t:"отчетам;"},{k:"li",t:"API;"},{k:"li",t:"иным ресурсам или функциям."},{k:"p",t:"10.4. Условия выбранного Тарифа являются частью Договора."},{k:"h",t:"11. Переменная плата и лимиты использования"},{k:"p",t:"11.1. Если Тариф предусматривает оплату в зависимости от числа заказов, операций, объема использования или иных показателей, расчет производится на основании данных НЭК CRM."},{k:"p",t:"11.2. Методика расчета переменной части цены должна быть указана в описании соответствующего Тарифа."},{k:"p",t:"11.3. В зависимости от Тарифа расчетным событием может являться создание, проведение, завершение заказа либо иное прямо указанное действие."},{k:"p",t:"11.4. Удаление записи после наступления расчетного события само по себе не отменяет начисленную плату, если иное предусмотрено Тарифом."},{k:"p",t:"11.5. Заказчик не вправе намеренно:"},{k:"li",t:"скрывать операции;"},{k:"li",t:"создавать дублирующие аккаунты;"},{k:"li",t:"обходить лимиты;"},{k:"li",t:"удалять или изменять сведения исключительно с целью искусственного уменьшения платы."},{k:"p",t:"11.6. При выявлении очевидной технической ошибки расчета Исполнитель производит корректировку."},{k:"h",t:"12. Порядок оплаты"},{k:"p",t:"12.1. Если Тарифом не предусмотрено иное, доступ предоставляется на условиях предварительной оплаты."},{k:"p",t:"12.2. Оплата может производиться доступными на Сайте или согласованными Сторонами способами, включая:"},{k:"li",t:"банковскую карту;"},{k:"li",t:"Систему быстрых платежей;"},{k:"li",t:"безналичный перевод по счету;"},{k:"li",t:"иные доступные платежные способы."},{k:"p",t:"12.3. Обязанность Заказчика по оплате считается исполненной после поступления денежных средств Исполнителю либо подтверждения успешного платежа соответствующей платежной системой."},{k:"p",t:"12.4. Банковские комиссии и иные расходы плательщика оплачиваются Заказчиком, если иное прямо не указано Исполнителем."},{k:"p",t:"12.5. Стоимость указывается в российских рублях."},{k:"p",t:"12.6. Налоговый режим и наличие либо отсутствие НДС отражаются Исполнителем в платежных и расчетных документах в соответствии с применимым законодательством."},{k:"h",t:"13. Кассовые чеки и платежные документы"},{k:"p",t:"13.1. В случаях, когда законодательством Российской Федерации предусмотрено применение контрольно-кассовой техники, Исполнитель формирует кассовые чеки в установленном порядке."},{k:"p",t:"13.2. Электронный чек может направляться на предоставленный Заказчиком номер телефона или адрес электронной почты."},{k:"p",t:"13.3. Заказчик отвечает за правильность предоставленных контактных данных для направления расчетных документов."},{k:"p",t:"13.4. При оплате по счету платежные и бухгалтерские документы предоставляются в порядке, предусмотренном законодательством и настоящей Офертой."},{k:"h",t:"14. Электронный документооборот"},{k:"p",t:"14.1. Стороны вправе осуществлять обмен документами в электронной форме."},{k:"p",t:"14.2. Для обмена формализованными и первичными учетными документами Стороны вправе использовать оператора электронного документооборота и электронные подписи соответствующего вида."},{k:"p",t:"14.3. Подключение к конкретному оператору ЭДО может осуществляться путем взаимного принятия приглашения в соответствующей системе."},{k:"p",t:"14.4. Электронные первичные учетные документы подписываются электронной подписью в случаях и порядке, предусмотренных законодательством Российской Федерации."},{k:"p",t:"14.5. Счета, уведомления, отчеты и иные информационные документы могут размещаться:"},{k:"li",t:"в Личном кабинете;"},{k:"li",t:"направляться по электронной почте;"},{k:"li",t:"передаваться через ЭДО."},{k:"p",t:"14.6. До подключения полноценного ЭДО Стороны вправе обмениваться электронными копиями документов посредством адресов электронной почты, указанных ими в рамках Договора, если для соответствующего документа законодательством не установлен обязательный иной способ оформления."},{k:"h",t:"15. Подтверждение предоставления доступа и приемка"},{k:"p",t:"15.1. Доступ к НЭК CRM считается предоставленным с момента технической активации соответствующего Тарифа для учетной записи Заказчика."},{k:"p",t:"15.2. Факт предоставления доступа может подтверждаться данными информационной системы Исполнителя."},{k:"p",t:"15.3. Подписание отдельного акта предоставления доступа не является обязательным, если иное не установлено Тарифом или отдельным соглашением."},{k:"p",t:"15.4. По запросу Заказчика либо при использовании соответствующего способа расчетов Исполнитель вправе формировать акт, УПД или иной предусмотренный законом документ."},{k:"p",t:"15.5. Если Исполнитель направил Заказчику акт оказанных услуг или иной документ, Заказчик обязан в течение 5 рабочих дней:"},{k:"li",t:"подписать его;"},{k:"li",t:"либо направить мотивированные письменные возражения."},{k:"p",t:"При отсутствии мотивированных возражений в указанный срок услуги в соответствующей части считаются принятыми без замечаний, если такой порядок допустим законодательством и характером соответствующего обязательства."},{k:"h",t:"16. Автоматическое продление и рекуррентные платежи"},{k:"p",t:"16.1. Автоматическое продление и автоматическое списание денежных средств применяются только в случае, если Заказчик отдельно активировал соответствующую функцию."},{k:"p",t:"16.2. Сам по себе акцепт Оферты не означает согласия на бессрочные автоматические списания."},{k:"p",t:"16.3. Заказчик вправе отключить автоматическое продление предусмотренным интерфейсом способом."},{k:"p",t:"16.4. После отключения автопродления оплаченный доступ сохраняется до окончания уже оплаченного периода."},{k:"h",t:"17. Бесплатный и тестовый доступ"},{k:"p",t:"17.1. Исполнитель вправе предоставлять бесплатный, тестовый или льготный доступ."},{k:"p",t:"17.2. Продолжительность, состав функций и лимиты такого доступа определяются Исполнителем."},{k:"p",t:"17.3. Бесплатный доступ может быть прекращен после окончания заявленного срока."},{k:"p",t:"17.4. Если иное прямо не указано, переход на платный Тариф требует отдельного действия Заказчика и не осуществляется путем автоматического списания без предусмотренного для этого основания."},{k:"h",t:"18. Права Исполнителя"},{k:"p",t:"Исполнитель вправе:"},{k:"p",t:"18.1. Получать плату в соответствии с выбранным Тарифом."},{k:"p",t:"18.2. Обновлять и совершенствовать Сервис."},{k:"p",t:"18.3. Проводить технические работы."},{k:"p",t:"18.4. Устанавливать разумные технические ограничения, необходимые для стабильности и безопасности Сервиса."},{k:"p",t:"18.5. Ограничивать доступ в случаях, предусмотренных Договором."},{k:"p",t:"18.6. Использовать обезличенные и агрегированные сведения о работе Сервиса для:"},{k:"li",t:"анализа нагрузки;"},{k:"li",t:"развития функциональности;"},{k:"li",t:"выявления технических проблем;"},{k:"li",t:"формирования общей статистики."},{k:"p",t:"Такие сведения не должны использоваться для идентификации клиентов Заказчика."},{k:"p",t:"18.7. Привлекать третьих лиц для технического обеспечения Сервиса с соблюдением требований к персональным данным и конфиденциальности."},{k:"h",t:"19. Обязанности Исполнителя"},{k:"p",t:"Исполнитель обязуется:"},{k:"p",t:"19.1. Предоставлять Заказчику доступ к НЭК CRM в пределах оплаченного Тарифа."},{k:"p",t:"19.2. Принимать разумные меры для обеспечения работоспособности Сервиса."},{k:"p",t:"19.3. Принимать необходимые организационные и технические меры безопасности."},{k:"p",t:"19.4. Соблюдать конфиденциальность Клиентских данных."},{k:"p",t:"19.5. Не использовать клиентскую базу Заказчика для:"},{k:"li",t:"собственной рекламы;"},{k:"li",t:"прямого привлечения клиентов Заказчика;"},{k:"li",t:"продажи третьим лицам;"},{k:"li",t:"формирования собственной клиентской базы."},{k:"p",t:"19.6. Обеспечивать обработку Клиентских данных в соответствии с Поручением на обработку персональных данных."},{k:"p",t:"19.7. Предоставлять Заказчику предусмотренные Сервисом средства экспорта данных."},{k:"h",t:"20. Права Заказчика"},{k:"p",t:"Заказчик вправе:"},{k:"p",t:"20.1. Пользоваться НЭК CRM в пределах выбранного Тарифа."},{k:"p",t:"20.2. Создавать учетные записи работников в предусмотренном Тарифом количестве."},{k:"p",t:"20.3. Управлять правами доступа."},{k:"p",t:"20.4. Размещать в Сервисе законно обрабатываемую информацию."},{k:"p",t:"20.5. Экспортировать свои данные средствами Сервиса."},{k:"p",t:"20.6. Обращаться в техническую поддержку."},{k:"p",t:"20.7. Отказаться от дальнейшего использования Сервиса в порядке настоящей Оферты."},{k:"h",t:"21. Обязанности Заказчика"},{k:"p",t:"Заказчик обязан:"},{k:"p",t:"21.1. Своевременно оплачивать использование Сервиса."},{k:"p",t:"21.2. Соблюдать законодательство Российской Федерации."},{k:"p",t:"21.3. Обеспечивать законность информации, размещаемой им в НЭК CRM."},{k:"p",t:"21.4. Иметь законные основания для обработки персональных данных своих клиентов и иных лиц."},{k:"p",t:"21.5. Обеспечивать правильное распределение прав доступа между своими работниками."},{k:"p",t:"21.6. Не предоставлять доступ к учетной записи неуполномоченным лицам."},{k:"p",t:"21.7. Не совершать действий, нарушающих стабильность или безопасность Сервиса."},{k:"p",t:"21.8. Самостоятельно проверять корректность документов, реквизитов, налоговых параметров и иной информации, которую он использует в своей хозяйственной деятельности."},{k:"h",t:"22. Контент и данные Заказчика"},{k:"p",t:"22.1. Заказчик сохраняет все права на принадлежащую ему информацию, размещенную в НЭК CRM."},{k:"p",t:"22.2. Размещение данных в НЭК CRM не передает Исполнителю право собственности или исключительные права на клиентскую базу Заказчика."},{k:"p",t:"22.3. Заказчик предоставляет Исполнителю только те технические полномочия на обработку данных, которые необходимы для исполнения Договора и Поручения на обработку персональных данных."},{k:"p",t:"22.4. Заказчик самостоятельно отвечает за содержание размещенной им информации."},{k:"p",t:"22.5. Запрещается использовать НЭК CRM для хранения или распространения:"},{k:"li",t:"информации, оборот которой запрещен законом;"},{k:"li",t:"вредоносного программного обеспечения;"},{k:"li",t:"сведений, полученных заведомо незаконным способом;"},{k:"li",t:"государственных секретов;"},{k:"li",t:"иных данных, обработка которых посредством НЭК CRM прямо запрещена законодательством."},{k:"p",t:"22.6. Специальные категории и биометрические персональные данные не должны целенаправленно размещаться в Сервисе, кроме случаев, отдельно предусмотренных функциональностью, законом и соглашением Сторон."},{k:"h",t:"23. Персональные данные клиентов Заказчика"},{k:"p",t:"23.1. В отношении персональных данных клиентов, работников, представителей, контрагентов и иных физических лиц, которые Заказчик самостоятельно размещает в НЭК CRM для собственных целей, Заказчик является оператором персональных данных, если именно он определяет цели, состав и способы соответствующей обработки."},{k:"p",t:"23.2. Исполнитель осуществляет обработку таких данных по поручению Заказчика."},{k:"p",t:"23.3. Условия обработки определяются Приложением № 1 «Поручение на обработку персональных данных», являющимся неотъемлемой частью настоящего Договора."},{k:"p",t:"23.4. Акцептуя Оферту, Заказчик одновременно предоставляет Исполнителю Поручение на обработку персональных данных на условиях Приложения № 1."},{k:"p",t:"23.5. Заказчик самостоятельно обеспечивает наличие законных оснований для:"},{k:"li",t:"сбора персональных данных;"},{k:"li",t:"их внесения в НЭК CRM;"},{k:"li",t:"поручения их обработки Исполнителю;"},{k:"li",t:"использования соответствующих данных в своей деятельности."},{k:"p",t:"23.6. Исполнитель не обязан самостоятельно получать согласие непосредственно у клиента Заказчика на обработку, осуществляемую исключительно по поручению Заказчика."},{k:"h",t:"24. Персональные данные Пользователей НЭК CRM"},{k:"p",t:"24.1. Обработка персональных данных самого Пользователя НЭК CRM осуществляется Исполнителем в соответствии с Политикой обработки персональных данных."},{k:"p",t:"24.2. В случаях, когда для обработки требуется согласие субъекта персональных данных, оно предоставляется посредством отдельного подтверждающего действия."},{k:"p",t:"24.3. Принятие настоящей Оферты не заменяет отдельное согласие на обработку персональных данных."},{k:"p",t:"24.4. Согласие на получение рекламных сообщений также оформляется отдельно, когда его получение требуется законом."},{k:"h",t:"25. Интеграции с внешними сервисами"},{k:"p",t:"25.1. НЭК CRM может предоставлять интеграции с:"},{k:"li",t:"телефонией;"},{k:"li",t:"электронной почтой;"},{k:"li",t:"SMS;"},{k:"li",t:"мессенджерами;"},{k:"li",t:"платежными системами;"},{k:"li",t:"кассовым оборудованием;"},{k:"li",t:"операторами фискальных данных;"},{k:"li",t:"иными внешними сервисами."},{k:"p",t:"25.2. Работа внешней интеграции может зависеть от соответствующего третьего лица."},{k:"p",t:"25.3. Исполнитель не контролирует правила, тарифы и техническую доступность независимых сторонних сервисов."},{k:"p",t:"25.4. Заказчик самостоятельно заключает необходимые договоры с поставщиками сторонних сервисов, если иное прямо не предусмотрено Тарифом."},{k:"p",t:"25.5. Если Заказчик предоставляет НЭК CRM токен, API-ключ или иные учетные данные внешнего сервиса, он подтверждает наличие права на их использование."},{k:"p",t:"25.6. Исполнитель принимает разумные меры для защиты предоставленных технических ключей."},{k:"h",t:"26. Кассовое оборудование и финансовые функции"},{k:"p",t:"26.1. Если НЭК CRM интегрирована с кассовым оборудованием, платежной системой или оператором фискальных данных, Сервис выполняет технические функции в пределах соответствующей интеграции."},{k:"p",t:"26.2. Если иное прямо не предусмотрено отдельным соглашением, Исполнитель не является:"},{k:"li",t:"кассиром Заказчика;"},{k:"li",t:"платежным агентом Заказчика;"},{k:"li",t:"бухгалтером Заказчика;"},{k:"li",t:"налоговым консультантом."},{k:"p",t:"26.3. Заказчик самостоятельно отвечает за правильность:"},{k:"li",t:"применяемой системы налогообложения;"},{k:"li",t:"ставок налогов;"},{k:"li",t:"наименований предметов расчета;"},{k:"li",t:"признаков способа и предмета расчета;"},{k:"li",t:"реквизитов чеков;"},{k:"li",t:"применения ККТ;"},{k:"li",t:"иных сведений, формируемых на основании введенных Заказчиком данных."},{k:"h",t:"27. Документы, формируемые НЭК CRM"},{k:"p",t:"27.1. НЭК CRM может предоставлять техническую возможность формирования:"},{k:"li",t:"актов приема-передачи;"},{k:"li",t:"заказ-нарядов;"},{k:"li",t:"квитанций;"},{k:"li",t:"гарантийных документов;"},{k:"li",t:"счетов;"},{k:"li",t:"отчетов;"},{k:"li",t:"иных документов."},{k:"p",t:"27.2. Такие функции являются инструментом автоматизации."},{k:"p",t:"27.3. Заказчик самостоятельно определяет применимость конкретной формы документа к своей деятельности и обеспечивает соответствие документа:"},{k:"li",t:"характеру своих правоотношений;"},{k:"li",t:"фактическим обстоятельствам;"},{k:"li",t:"законодательству;"},{k:"li",t:"своим внутренним правилам."},{k:"p",t:"27.4. Использование шаблона НЭК CRM само по себе не является юридической, налоговой или бухгалтерской консультацией."},{k:"h",t:"28. Техническая поддержка"},{k:"p",t:"28.1. Техническая поддержка осуществляется посредством каналов, указанных на Сайте или в интерфейсе НЭК CRM."},{k:"p",t:"28.2. Если Тарифом не установлен гарантированный срок реакции, обращения рассматриваются в порядке очередности с учетом их характера и критичности."},{k:"p",t:"28.3. Техническая поддержка не включает выполнение за Заказчика его хозяйственных, бухгалтерских, кадровых или юридических обязанностей."},{k:"h",t:"29. Доступность Сервиса"},{k:"p",t:"29.1. Исполнитель принимает разумные меры для обеспечения стабильной доступности НЭК CRM."},{k:"p",t:"29.2. Если отдельным соглашением или Тарифом не установлен SLA, Исполнитель не гарантирует абсолютную непрерывность работы Сервиса 24 часа в сутки 365 дней в году."},{k:"p",t:"29.3. Временная недоступность может быть связана с:"},{k:"li",t:"техническим обслуживанием;"},{k:"li",t:"обновлением;"},{k:"li",t:"устранением уязвимостей;"},{k:"li",t:"авариями;"},{k:"li",t:"сбоями оборудования;"},{k:"li",t:"работой дата-центра;"},{k:"li",t:"сетевыми проблемами;"},{k:"li",t:"действиями поставщиков инфраструктуры;"},{k:"li",t:"действиями государственных органов;"},{k:"li",t:"иными обстоятельствами."},{k:"p",t:"29.4. Плановые работы по возможности проводятся таким образом, чтобы минимизировать влияние на Пользователей."},{k:"p",t:"29.5. О продолжительных плановых работах Исполнитель по возможности уведомляет заранее."},{k:"h",t:"30. Резервное копирование"},{k:"p",t:"30.1. Исполнитель вправе создавать резервные копии информации, необходимой для работы НЭК CRM."},{k:"p",t:"30.2. Резервные копии создаются исключительно в целях:"},{k:"li",t:"восстановления;"},{k:"li",t:"обеспечения отказоустойчивости;"},{k:"li",t:"защиты от технической потери информации."},{k:"p",t:"30.3. Создание резервных копий не освобождает Заказчика от обязанности экспортировать критически важную для него информацию, если необходимость иметь независимую копию обусловлена характером его деятельности."},{k:"p",t:"30.4. Удаленные из основной системы данные могут технически сохраняться в резервных копиях до завершения установленного цикла их ротации."},{k:"p",t:"30.5. Такие данные не должны использоваться для обычной деятельности после их удаления из основной базы и уничтожаются по мере обновления соответствующих резервных копий, если иное не требуется законом."},{k:"h",t:"31. Экспорт данных"},{k:"p",t:"31.1. Заказчик вправе экспортировать свои данные в форматах, поддерживаемых НЭК CRM."},{k:"p",t:"31.2. Исполнитель вправе изменять технический формат экспорта при сохранении возможности получить основные данные Заказчика в машиночитаемом либо ином предусмотренном Сервисом виде."},{k:"p",t:"31.3. Перед прекращением использования НЭК CRM Заказчику рекомендуется самостоятельно выполнить экспорт необходимой информации."},{k:"p",t:"31.4. При технической возможности Исполнитель может оказать помощь в подготовке дополнительной выгрузки на условиях, согласованных Сторонами отдельно."},{k:"h",t:"32. Приостановление доступа"},{k:"p",t:"32.1. Исполнитель вправе временно ограничить или приостановить доступ к Сервису:"},{k:"li",t:"при наличии задолженности;"},{k:"li",t:"при превышении предусмотренных Тарифом лимитов;"},{k:"li",t:"при выявлении угрозы информационной безопасности;"},{k:"li",t:"при компрометации учетной записи;"},{k:"li",t:"при использовании Сервиса для противоправных действий;"},{k:"li",t:"при существенном нарушении настоящей Оферты;"},{k:"li",t:"по законному требованию государственного органа;"},{k:"li",t:"для проведения необходимых аварийных работ."},{k:"p",t:"32.2. Если нарушение может быть устранено без немедленной блокировки, Исполнитель вправе предварительно предложить Заказчику устранить его."},{k:"p",t:"32.3. При угрозе безопасности или необходимости исполнения закона доступ может быть ограничен без предварительного уведомления."},{k:"p",t:"32.4. После устранения основания ограничение снимается, если продолжение Договора возможно."},{k:"h",t:"33. Истечение оплаченного периода"},{k:"p",t:"33.1. После истечения оплаченного периода Исполнитель вправе:"},{k:"li",t:"прекратить доступ к платным функциям;"},{k:"li",t:"перевести учетную запись в ограниченный или режим только для чтения;"},{k:"li",t:"приостановить создание и изменение данных."},{k:"p",t:"33.2. Само окончание оплаченного периода не означает немедленного уничтожения данных."},{k:"p",t:"33.3. Если Договор не продлен, применяются правила раздела 36 настоящей Оферты."},{k:"h",t:"34. Срок Договора"},{k:"p",t:"34.1. Договор вступает в силу с момента акцепта."},{k:"p",t:"34.2. Договор действует до его прекращения в соответствии с настоящей Офертой."},{k:"p",t:"34.3. Право использования платной функциональности действует в течение оплаченного периода."},{k:"p",t:"34.4. Продление осуществляется путем оплаты следующего периода либо автоматического продления, если оно отдельно подключено Заказчиком."},{k:"h",t:"35. Отказ от Договора и возврат денежных средств"},{k:"p",t:"35.1. Заказчик вправе прекратить использование НЭК CRM и отказаться от дальнейшего исполнения Договора путем:"},{k:"li",t:"отключения продления;"},{k:"li",t:"направления уведомления Исполнителю;"},{k:"li",t:"использования соответствующей функции Личного кабинета."},{k:"p",t:"35.2. Сам факт того, что Заказчик не использовал доступ при технической возможности его использования, не означает непредоставления доступа Исполнителем."},{k:"p",t:"35.3. При досрочном прекращении Договора расчет между Сторонами производится с учетом:"},{k:"li",t:"стоимости фактически предоставленного периода доступа;"},{k:"li",t:"объема фактически оказанных дополнительных услуг;"},{k:"li",t:"фактически понесенных Исполнителем расходов;"},{k:"li",t:"условий соответствующего Тарифа;"},{k:"li",t:"требований законодательства Российской Федерации."},{k:"p",t:"35.4. Если для конкретного Тарифа установлены специальные правила перерасчета или возврата, такие правила являются частью Тарифа."},{k:"p",t:"35.5. Денежные средства, полученные за период или услуги, которые фактически не были предоставлены и не подлежат оплате на ином законном основании, возвращаются Заказчику."},{k:"p",t:"35.6. Возврат осуществляется тем же способом, которым была произведена оплата, если это технически возможно, либо по указанным Заказчиком банковским реквизитам."},{k:"h",t:"36. Данные после прекращения Договора"},{k:"p",t:"36.1. После прекращения Договора Исполнитель прекращает обычную обработку клиентской базы Заказчика."},{k:"p",t:"36.2. В течение периода до 30 календарных дней после прекращения Договора данные могут сохраняться в ограниченном режиме исключительно для:"},{k:"li",t:"возможности их выгрузки;"},{k:"li",t:"восстановления доступа при ошибочном прекращении;"},{k:"li",t:"завершения обязательств Сторон;"},{k:"li",t:"выполнения требований законодательства;"},{k:"li",t:"технического удаления данных."},{k:"p",t:"36.3. Исполнитель не обязан сохранять полную функциональность аккаунта в течение данного периода."},{k:"p",t:"36.4. По истечении указанного срока персональные данные и Контент Заказчика удаляются из основной информационной системы при отсутствии иных законных оснований для хранения."},{k:"p",t:"36.5. Отдельные технические копии могут сохраняться в резервных копиях до окончания установленного цикла ротации, при этом они исключаются из обычного использования."},{k:"p",t:"36.6. Заказчик обязан заблаговременно выгрузить сведения, которые он обязан сохранять в силу законодательства или внутренних требований."},{k:"h",t:"37. Конфиденциальность"},{k:"p",t:"37.1. Стороны обязуются соблюдать конфиденциальность информации, полученной в связи с исполнением Договора и имеющей конфиденциальный характер."},{k:"p",t:"37.2. Клиентская база Заказчика является конфиденциальной информацией независимо от того, имеет ли она самостоятельный режим коммерческой тайны."},{k:"p",t:"37.3. Исполнитель не получает имущественных прав на клиентскую базу Заказчика."},{k:"p",t:"37.4. Исполнитель вправе предоставлять доступ к конфиденциальной информации своим работникам и подрядчикам только в объеме, необходимом для исполнения их обязанностей."},{k:"p",t:"37.5. Обязательство конфиденциальности сохраняется после прекращения Договора."},{k:"p",t:"37.6. Не признается нарушением раскрытие информации:"},{k:"li",t:"по законному требованию государственного органа или суда;"},{k:"li",t:"с согласия соответствующей Стороны;"},{k:"li",t:"если информация стала общедоступной не вследствие нарушения Договора;"},{k:"li",t:"в иных предусмотренных законом случаях."},{k:"h",t:"38. Интеллектуальная собственность"},{k:"p",t:"38.1. Все исключительные права на НЭК CRM и охраняемые элементы Сервиса принадлежат Исполнителю и (или) соответствующим правообладателям."},{k:"p",t:"38.2. Настоящий Договор не предусматривает отчуждение исключительных прав."},{k:"p",t:"38.3. Заказчику предоставляется только прямо предусмотренное Договором право использования."},{k:"p",t:"38.4. Торговые обозначения, логотипы, дизайн и иные элементы индивидуализации не могут использоваться Заказчиком вне обычной работы с Сервисом без согласия правообладателя."},{k:"p",t:"38.5. Предоставление Заказчиком предложений по улучшению НЭК CRM не ограничивает Исполнителя в праве реализовывать аналогичные идеи и функции при условии отсутствия неправомерного использования охраняемой конфиденциальной информации Заказчика."},{k:"h",t:"39. Ответственность Заказчика"},{k:"p",t:"39.1. Заказчик несет ответственность за:"},{k:"li",t:"законность своей деятельности;"},{k:"li",t:"законность обработки клиентских данных;"},{k:"li",t:"действия своих Пользователей;"},{k:"li",t:"достоверность введенных сведений;"},{k:"li",t:"содержание формируемых им документов;"},{k:"li",t:"безопасность собственных учетных данных;"},{k:"li",t:"правильность настроек доступа;"},{k:"li",t:"законность использования сторонних интеграций."},{k:"p",t:"39.2. Заказчик самостоятельно урегулирует требования третьих лиц, возникшие вследствие незаконного размещения им информации, если нарушение не вызвано действиями Исполнителя."},{k:"h",t:"40. Ответственность Исполнителя"},{k:"p",t:"40.1. Исполнитель несет ответственность за нарушение Договора при наличии предусмотренных законодательством оснований."},{k:"p",t:"40.2. Если иное прямо не предусмотрено законом, Исполнитель не отвечает за последствия:"},{k:"li",t:"неправильного ввода данных Заказчиком;"},{k:"li",t:"действий Пользователей Заказчика;"},{k:"li",t:"передачи учетных данных посторонним лицам;"},{k:"li",t:"использования устаревшего или несовместимого оборудования и программного обеспечения Заказчика;"},{k:"li",t:"неисправности сети Интернет Заказчика;"},{k:"li",t:"сбоев независимых сторонних сервисов;"},{k:"li",t:"действий государственных органов;"},{k:"li",t:"неправомерных действий третьих лиц, которые Исполнитель объективно не мог предотвратить при принятии разумных мер безопасности."},{k:"p",t:"40.3. Если иное не установлено законом или отдельным SLA, ответственность Исполнителя за доказанные убытки по Договору ограничивается суммой платежей, фактически полученных Исполнителем от соответствующего Заказчика за три календарных месяца, непосредственно предшествовавших событию, послужившему основанием ответственности."},{k:"p",t:"Если Договор действовал менее трех месяцев — суммой платежей за фактический срок его действия."},{k:"p",t:"40.4. Ограничение ответственности не применяется в случаях, когда такое ограничение прямо запрещено законодательством Российской Федерации."},{k:"p",t:"40.5. Никакое положение Договора не освобождает Сторону от ответственности за умышленное нарушение обязательства в случаях, когда такое освобождение или ограничение недопустимо законом."},{k:"h",t:"41. Отсутствие гарантии хозяйственного результата"},{k:"p",t:"41.1. НЭК CRM является инструментом автоматизации деятельности."},{k:"p",t:"41.2. Исполнитель не гарантирует:"},{k:"li",t:"увеличение выручки;"},{k:"li",t:"рост количества клиентов;"},{k:"li",t:"прибыльность бизнеса;"},{k:"li",t:"отсутствие претензий клиентов Заказчика;"},{k:"li",t:"достижение иного конкретного коммерческого результата."},{k:"p",t:"41.3. Решения о ведении бизнеса, ценах, ремонте устройств, работе с клиентами, налогах и документах принимаются Заказчиком самостоятельно."},{k:"h",t:"42. Обстоятельства непреодолимой силы"},{k:"p",t:"42.1. Сторона освобождается от ответственности за неисполнение обязательства вследствие чрезвычайных и непредотвратимых при данных условиях обстоятельств в предусмотренном законодательством порядке."},{k:"p",t:"42.2. К таким обстоятельствам могут относиться, если они отвечают признакам непреодолимой силы:"},{k:"li",t:"стихийные бедствия;"},{k:"li",t:"военные действия;"},{k:"li",t:"массовые беспорядки;"},{k:"li",t:"чрезвычайные ситуации;"},{k:"li",t:"обязательные акты государственных органов;"},{k:"li",t:"масштабные аварии инфраструктуры;"},{k:"li",t:"иные чрезвычайные обстоятельства."},{k:"p",t:"42.3. Обычные технические неисправности, отсутствие денежных средств или нарушение обязательств контрагентами сами по себе не признаются непреодолимой силой, если не обусловлены соответствующими чрезвычайными обстоятельствами."},{k:"h",t:"43. Юридически значимые сообщения"},{k:"p",t:"43.1. Стороны признают юридически значимыми сообщения, направленные:"},{k:"li",t:"через Личный кабинет;"},{k:"li",t:"на адрес электронной почты, указанный Заказчиком;"},{k:"li",t:"через ЭДО;"},{k:"li",t:"по почтовому адресу Стороны;"},{k:"li",t:"иным согласованным способом."},{k:"p",t:"43.2. Заказчик обязан поддерживать актуальность своих контактных данных."},{k:"p",t:"43.3. Риск последствий неполучения сообщения из-за неактуального адреса электронной почты или иных данных несет Сторона, не уведомившая об их изменении."},{k:"p",t:"43.4. Сообщение считается доставленным с момента, когда оно стало доступно адресату по указанному им каналу связи, если иное не установлено законодательством."},{k:"h",t:"44. Изменение Оферты"},{k:"p",t:"44.1. Исполнитель вправе изменять условия настоящей Оферты."},{k:"p",t:"44.2. Актуальная редакция размещается на Сайте."},{k:"p",t:"44.3. Если изменение существенно влияет на права и обязанности действующих Заказчиков, Исполнитель уведомляет их через НЭК CRM или электронную почту, как правило, не позднее чем за 10 календарных дней до вступления изменения в силу."},{k:"p",t:"44.4. Изменения, вызванные требованиями законодательства, устранением угроз безопасности или предотвращением злоупотреблений, могут вступать в силу ранее."},{k:"p",t:"44.5. Новые условия не изменяют стоимость уже полностью оплаченного периода доступа, если иное не требуется законодательством или не согласовано с Заказчиком."},{k:"p",t:"44.6. Продолжение использования Сервиса после вступления новой редакции в силу означает принятие измененных договорных условий в той мере, в которой такой способ изменения допускается законодательством и настоящим Договором."},{k:"p",t:"44.7. Если Заказчик не согласен с изменениями, он вправе отказаться от продления Договора до начала следующего оплачиваемого периода."},{k:"h",t:"45. Изменение Тарифов"},{k:"p",t:"45.1. Исполнитель вправе изменять стоимость и состав Тарифов."},{k:"p",t:"45.2. Изменение цены не распространяется на уже оплаченный период."},{k:"p",t:"45.3. Новая цена применяется при следующем продлении или приобретении нового периода."},{k:"p",t:"45.4. О плановом изменении стоимости действующего Тарифа Исполнитель по возможности уведомляет Заказчика не позднее чем за 30 календарных дней до следующего списания или продления."},{k:"h",t:"46. Претензионный порядок"},{k:"p",t:"46.1. Стороны стремятся разрешать разногласия путем переговоров."},{k:"p",t:"46.2. До обращения в суд Сторона направляет другой Стороне претензию, если обязательный досудебный порядок применим к соответствующему спору."},{k:"p",t:"46.3. Претензия может направляться:"},{k:"li",t:"через ЭДО;"},{k:"li",t:"на согласованный адрес электронной почты;"},{k:"li",t:"почтовым отправлением;"},{k:"li",t:"иным способом, позволяющим подтвердить ее направление и содержание."},{k:"p",t:"46.4. Срок рассмотрения претензии составляет 15 рабочих дней с момента ее получения, если иной срок не установлен законом."},{k:"h",t:"47. Применимое право и разрешение споров"},{k:"p",t:"47.1. К настоящему Договору применяется законодательство Российской Федерации."},{k:"p",t:"47.2. Если спор не урегулирован путем переговоров, он передается в компетентный суд Российской Федерации."},{k:"p",t:"47.3. В случаях, когда договорная подсудность допускается законодательством, спор рассматривается по месту государственной регистрации Исполнителя."},{k:"p",t:"47.4. Правила настоящего раздела не изменяют исключительную или иную обязательную подсудность, установленную законом."},{k:"h",t:"48. Соотношение документов"},{k:"p",t:"48.1. Неотъемлемой частью договорных отношений являются:"},{k:"li",t:"настоящая Публичная оферта;"},{k:"li",t:"выбранный Тариф;"},{k:"li",t:"Приложение № 1 «Поручение на обработку персональных данных»;"},{k:"li",t:"иные прямо указанные в Оферте приложения."},{k:"p",t:"48.2. Политика обработки персональных данных является отдельным информационным документом Оператора."},{k:"p",t:"48.3. Согласие физического лица на обработку его персональных данных оформляется отдельно и не является частью акцепта Оферты."},{k:"p",t:"48.4. Согласие на рекламные и маркетинговые сообщения, если оно требуется, также оформляется отдельно."},{k:"p",t:"48.5. При противоречии между настоящей Офертой и Поручением в части обработки Клиентских данных применяются условия Поручения."},{k:"p",t:"48.6. Условия конкретного Тарифа имеют приоритет в вопросах цены, срока, лимитов и состава предоставляемой функциональности."},{k:"h",t:"49. Заключительные положения"},{k:"p",t:"49.1. Если отдельное положение Договора признано недействительным, это не влечет недействительность остальных положений."},{k:"p",t:"49.2. Неосуществление Стороной какого-либо права не означает отказ от такого права в будущем."},{k:"p",t:"49.3. Заголовки разделов используются для удобства и не влияют на толкование условий."},{k:"p",t:"49.4. Заказчик не вправе передать Договор другому лицу без предварительного согласия Исполнителя, за исключением случаев универсального правопреемства или иных предусмотренных законом случаев."},{k:"p",t:"49.5. Исполнитель вправе привлекать третьих лиц к техническому исполнению Договора, оставаясь ответственным перед Заказчиком в предусмотренных законом и Договором пределах."},{k:"p",t:"49.6. Актуальная версия Оферты размещается по постоянному адресу:"},{k:"h",t:"https://nakcrm.ru/documents/offer"},{k:"p",t:"49.7. Исполнитель вправе сохранять архив предыдущих редакций Оферты."},{k:"h",t:"50. Реквизиты Исполнителя"},{k:"h",t:"Индивидуальный предприниматель Неклюдов Артем Анатольевич"},{k:"p",t:"ИНН: 263221164126"},{k:"p",t:"ОГРНИП: 324265100105224"},{k:"p",t:"Адрес для направления корреспонденции:"},{k:"p",t:"Электронная почта:SCRM@nakcrm.ru"},{k:"p",t:"Сайт:https://nakcrm.ru"},{k:"p",t:"Банковские и иные платежные реквизиты могут указываться в счете, платежной форме или ином расчетном документе Исполнителя."},{k:"h",t:"Приложение № 1"},{k:"h",t:"Поручение на обработку персональных данных"},{k:"p",t:"Приложение № 1 является неотъемлемой частью настоящей Публичной оферты и размещается по адресу:"},{k:"h",t:"https://nakcrm.ru/documents/personal-data-processing-agreement"},{k:"p",t:"Акцепт настоящей Оферты означает предоставление Заказчиком Исполнителю Поручения на обработку персональных данных в отношении данных, оператором которых является Заказчик, на условиях соответствующего Приложения."}]},{slug:"personal-data-processing-agreement",title:"Поручение на обработку персональных данных",subtitle:"Приложение № 1 к Публичной оферте",version:"",blocks:[{k:"h",t:"Приложение № 1"},{k:"h",t:"к Публичной оферте на предоставление доступа к сервису НЭК CRM"},{k:"h",t:"Поручение на обработку персональных данных"},{k:"h",t:"1. Общие положения"},{k:"p",t:"1.1. Настоящее Поручение на обработку персональных данных (далее — Поручение) является неотъемлемой частью договора на предоставление доступа к сервису НЭК CRM, заключаемого путем акцепта Публичной оферты индивидуального предпринимателя Неклюдова Артема Анатольевича."},{k:"p",t:"1.2. Для целей настоящего Поручения:"},{k:"p",t:"Оператор персональных данных (Оператор ПД) — Пользователь НЭК CRM, который самостоятельно или совместно с другими лицами организует и (или) осуществляет обработку персональных данных, а также определяет цели обработки персональных данных, состав персональных данных и действия, совершаемые с ними."},{k:"p",t:"Оператором ПД может являться индивидуальный предприниматель, юридическое лицо или физическое лицо в случаях, когда на него распространяются соответствующие требования законодательства Российской Федерации."},{k:"p",t:"Обработчик — индивидуальный предприниматель Неклюдов Артем Анатольевич, ИНН 263221164126, ОГРНИП 324265100105224, предоставляющий доступ к сервису НЭК CRM и осуществляющий обработку персональных данных по поручению Оператора ПД."},{k:"p",t:"Сервис / НЭК CRM — программный сервис, предназначенный для автоматизации деятельности сервисных центров и иных организаций и пользователей."},{k:"p",t:"Субъект персональных данных — физическое лицо, к которому относятся обрабатываемые персональные данные."},{k:"p",t:"1.3. В отношении персональных данных самого Пользователя НЭК CRM Обработчик в предусмотренных законодательством случаях может самостоятельно выступать оператором персональных данных."},{k:"p",t:"В отношении персональных данных клиентов, работников, представителей, контрагентов и иных лиц, которые Пользователь самостоятельно размещает в НЭК CRM для собственных целей, Пользователь выступает Оператором ПД, а НЭК CRM осуществляет обработку таких данных по настоящему Поручению."},{k:"p",t:"1.4. Акцептуя Публичную оферту, Оператор ПД поручает Обработчику обработку персональных данных на условиях настоящего Поручения."},{k:"p",t:"Лицо, совершающее акцепт от имени юридического лица или индивидуального предпринимателя, подтверждает наличие необходимых полномочий на заключение договора и предоставление настоящего Поручения."},{k:"h",t:"2. Предмет Поручения"},{k:"p",t:"2.1. Оператор ПД поручает Обработчику осуществлять обработку персональных данных, размещаемых, передаваемых или создаваемых Оператором ПД при использовании НЭК CRM, исключительно в целях предоставления функциональных возможностей Сервиса и исполнения договора."},{k:"p",t:"2.2. Обработчик осуществляет обработку персональных данных только:"},{k:"li",t:"в пределах настоящего Поручения;"},{k:"li",t:"в соответствии с документированными действиями и настройками Оператора ПД в НЭК CRM;"},{k:"li",t:"в объеме, необходимом для функционирования Сервиса;"},{k:"li",t:"в соответствии с законодательством Российской Федерации."},{k:"p",t:"2.3. Настоящее Поручение не предоставляет Обработчику права использовать персональные данные для самостоятельных целей, не связанных с предоставлением НЭК CRM, исполнением договора, обеспечением безопасности Сервиса или исполнением обязанностей, установленных законодательством Российской Федерации."},{k:"h",t:"3. Категории субъектов персональных данных"},{k:"p",t:"3.1. В рамках настоящего Поручения могут обрабатываться персональные данные следующих категорий физических лиц:"},{k:"li",t:"клиентов Оператора ПД;"},{k:"li",t:"потенциальных клиентов и заявителей;"},{k:"li",t:"работников и привлеченных специалистов Оператора ПД;"},{k:"li",t:"представителей клиентов и контрагентов;"},{k:"li",t:"представителей юридических лиц и индивидуальных предпринимателей;"},{k:"li",t:"контрагентов — физических лиц;"},{k:"li",t:"иных физических лиц, сведения о которых правомерно внесены Оператором ПД в НЭК CRM."},{k:"p",t:"3.2. Конкретные категории субъектов определяются Оператором ПД исходя из характера его деятельности и используемых функциональных возможностей НЭК CRM."},{k:"h",t:"4. Перечень обрабатываемых персональных данных"},{k:"p",t:"4.1. В рамках настоящего Поручения Обработчик может осуществлять обработку следующих персональных данных, самостоятельно внесенных Оператором ПД в НЭК CRM:"},{k:"li",t:"фамилия;"},{k:"li",t:"имя;"},{k:"li",t:"отчество;"},{k:"li",t:"номер телефона;"},{k:"li",t:"адрес электронной почты;"},{k:"li",t:"адрес и иные контактные сведения;"},{k:"li",t:"сведения о заказах, заявках и обращениях;"},{k:"li",t:"сведения о дате и истории обращений;"},{k:"li",t:"сведения о заключенных с субъектом договорах и заказах;"},{k:"li",t:"сведения о стоимости работ, оплатах и взаиморасчетах в пределах конкретного заказа;"},{k:"li",t:"сведения об устройстве или ином имуществе, переданном Оператору ПД;"},{k:"li",t:"марка и модель устройства;"},{k:"li",t:"серийный номер;"},{k:"li",t:"IMEI и иные технические идентификаторы устройства;"},{k:"li",t:"внешний вид, комплектность и состояние устройства;"},{k:"li",t:"заявленные неисправности и причины обращения;"},{k:"li",t:"сведения о запрошенных, выполненных и планируемых работах;"},{k:"li",t:"сведения об использованных или планируемых комплектующих;"},{k:"li",t:"история ремонта и обслуживания;"},{k:"li",t:"гарантийные сведения;"},{k:"li",t:"содержание комментариев и примечаний, внесенных Оператором ПД;"},{k:"li",t:"документы, фотографии, изображения и иные материалы, загруженные Оператором ПД;"},{k:"li",t:"сведения, необходимые для формирования актов приема-передачи, заказ-нарядов, гарантийных документов, квитанций и иных документов;"},{k:"li",t:"иные персональные данные, самостоятельно внесенные Оператором ПД в предусмотренные функционалом НЭК CRM поля."},{k:"p",t:"4.2. Состав обрабатываемых данных в каждом конкретном случае определяется Оператором ПД и должен соответствовать заявленным им целям обработки."},{k:"p",t:"4.3. Оператор ПД не должен вносить в НЭК CRM персональные данные, избыточные по отношению к соответствующим целям обработки."},{k:"h",t:"5. Специальные категории и биометрические персональные данные"},{k:"p",t:"5.1. НЭК CRM не предназначена для целенаправленной обработки специальных категорий персональных данных, касающихся расовой или национальной принадлежности, политических взглядов, религиозных или философских убеждений, состояния здоровья и интимной жизни субъектов персональных данных."},{k:"p",t:"5.2. НЭК CRM не предназначена для обработки биометрических персональных данных с целью установления личности физического лица."},{k:"p",t:"5.3. Оператор ПД обязуется не размещать такие данные в НЭК CRM, если необходимость их обработки прямо не предусмотрена используемым функционалом Сервиса, законодательством Российской Федерации и отдельным соглашением с Обработчиком."},{k:"h",t:"6. Цели обработки персональных данных"},{k:"p",t:"6.1. Обработка персональных данных осуществляется Обработчиком исключительно в целях технического обеспечения деятельности Оператора ПД посредством НЭК CRM, в том числе для:"},{k:"li",t:"создания и ведения клиентской базы;"},{k:"li",t:"учета клиентов и обращений;"},{k:"li",t:"регистрации и ведения заказов;"},{k:"li",t:"учета заявок и ремонтов;"},{k:"li",t:"хранения истории взаимодействия с клиентами;"},{k:"li",t:"хранения информации об устройствах;"},{k:"li",t:"ведения истории диагностики, обслуживания и ремонта;"},{k:"li",t:"учета выполненных и планируемых работ;"},{k:"li",t:"учета комплектующих;"},{k:"li",t:"формирования актов приема-передачи;"},{k:"li",t:"формирования заказ-нарядов;"},{k:"li",t:"формирования гарантийных документов;"},{k:"li",t:"формирования квитанций и иных документов;"},{k:"li",t:"поиска и систематизации информации;"},{k:"li",t:"отображения информации в интерфейсе НЭК CRM;"},{k:"li",t:"предоставления доступа уполномоченным Оператором ПД работникам;"},{k:"li",t:"реализации ролей и прав доступа;"},{k:"li",t:"формирования отчетов и статистики для Оператора ПД;"},{k:"li",t:"импорта и экспорта информации;"},{k:"li",t:"направления уведомлений клиентам Оператора ПД по его инициативе при использовании соответствующих функций НЭК CRM;"},{k:"li",t:"резервного копирования;"},{k:"li",t:"восстановления информации;"},{k:"li",t:"обеспечения доступности и сохранности информации;"},{k:"li",t:"технического сопровождения;"},{k:"li",t:"диагностики и устранения ошибок;"},{k:"li",t:"обеспечения информационной безопасности;"},{k:"li",t:"предотвращения несанкционированного доступа;"},{k:"li",t:"выполнения иных технических операций, непосредственно необходимых для предоставления функциональных возможностей НЭК CRM."},{k:"p",t:"6.2. Обработчик не определяет самостоятельные цели использования клиентской базы Оператора ПД."},{k:"h",t:"7. Перечень действий с персональными данными"},{k:"p",t:"7.1. В рамках настоящего Поручения Обработчику поручается осуществление следующих действий с персональными данными:"},{k:"li",t:"сбор в информационной системе НЭК CRM;"},{k:"li",t:"запись;"},{k:"li",t:"систематизация;"},{k:"li",t:"накопление;"},{k:"li",t:"хранение;"},{k:"li",t:"уточнение;"},{k:"li",t:"обновление;"},{k:"li",t:"изменение;"},{k:"li",t:"извлечение;"},{k:"li",t:"использование в пределах функциональных возможностей НЭК CRM;"},{k:"li",t:"копирование в случаях, необходимых для технической работы и резервного копирования;"},{k:"li",t:"предоставление доступа уполномоченным Оператором ПД лицам;"},{k:"li",t:"предоставление доступа лицам, привлекаемым для технического обеспечения работы НЭК CRM, в предусмотренных настоящим Поручением случаях;"},{k:"li",t:"обезличивание;"},{k:"li",t:"блокирование;"},{k:"li",t:"удаление;"},{k:"li",t:"уничтожение."},{k:"p",t:"7.2. Обработка осуществляется преимущественно с использованием средств автоматизации."},{k:"p",t:"Отдельные операции, связанные с технической поддержкой, расследованием инцидентов, восстановлением данных и исполнением требований Оператора ПД или законодательства Российской Федерации, могут осуществляться без использования средств автоматизации либо смешанным способом."},{k:"p",t:"7.3. Настоящее Поручение не предусматривает распространение персональных данных неопределенному кругу лиц."},{k:"h",t:"8. Обязанности Оператора ПД"},{k:"p",t:"8.1. Оператор ПД обязуется самостоятельно обеспечивать наличие законных оснований для обработки персональных данных, которые он размещает в НЭК CRM."},{k:"p",t:"8.2. В случаях, когда для поручения обработки персональных данных другому лицу законодательством требуется согласие субъекта персональных данных, Оператор ПД обеспечивает получение такого согласия до начала соответствующей обработки."},{k:"p",t:"8.3. Оператор ПД самостоятельно:"},{k:"li",t:"определяет цели обработки персональных данных;"},{k:"li",t:"определяет категории субъектов и состав обрабатываемых данных;"},{k:"li",t:"обеспечивает законность сбора персональных данных;"},{k:"li",t:"предоставляет субъектам необходимую информацию об обработке;"},{k:"li",t:"обеспечивает получение необходимых согласий;"},{k:"li",t:"определяет сроки обработки и хранения данных в пределах своей деятельности;"},{k:"li",t:"рассматривает запросы и обращения субъектов персональных данных;"},{k:"li",t:"принимает решения об уточнении, блокировании, прекращении обработки и уничтожении персональных данных."},{k:"p",t:"8.4. Оператор ПД гарантирует, что:"},{k:"li",t:"персональные данные получены законным способом;"},{k:"li",t:"их обработка соответствует заявленным целям;"},{k:"li",t:"объем данных не является избыточным;"},{k:"li",t:"передача и поручение обработки Обработчику имеют надлежащее правовое основание;"},{k:"li",t:"использование НЭК CRM для обработки таких данных не нарушает права субъектов персональных данных."},{k:"p",t:"8.5. Оператор ПД обязан своевременно сообщать Обработчику о требованиях субъектов персональных данных и иных обстоятельствах, требующих блокирования, исправления, прекращения обработки или уничтожения информации, если соответствующие действия невозможно выполнить самостоятельно средствами НЭК CRM."},{k:"p",t:"8.6. Оператор ПД самостоятельно определяет перечень своих работников и иных лиц, имеющих доступ к НЭК CRM, назначает им необходимые роли и права доступа и несет ответственность за действия таких лиц в пределах своей учетной записи."},{k:"p",t:"8.7. Оператор ПД обязан обеспечивать сохранность данных для входа в НЭК CRM и принимать разумные меры для предотвращения доступа к учетным записям неуполномоченных лиц."},{k:"p",t:"8.8. Оператор ПД не вправе давать Обработчику указания, выполнение которых заведомо нарушает законодательство Российской Федерации."},{k:"h",t:"9. Обязанности Обработчика"},{k:"p",t:"9.1. Обработчик обязуется соблюдать конфиденциальность персональных данных и не раскрывать их третьим лицам, за исключением случаев, предусмотренных настоящим Поручением или законодательством Российской Федерации."},{k:"p",t:"9.2. Обработчик обязуется соблюдать принципы и правила обработки персональных данных, предусмотренные законодательством Российской Федерации."},{k:"p",t:"9.3. Обработчик осуществляет обработку персональных данных только в целях и пределах настоящего Поручения."},{k:"p",t:"9.4. Обработчик принимает необходимые правовые, организационные и технические меры для защиты персональных данных от:"},{k:"li",t:"неправомерного или случайного доступа;"},{k:"li",t:"уничтожения;"},{k:"li",t:"изменения;"},{k:"li",t:"блокирования;"},{k:"li",t:"копирования;"},{k:"li",t:"неправомерного предоставления;"},{k:"li",t:"неправомерного распространения;"},{k:"li",t:"утраты;"},{k:"li",t:"иных неправомерных действий."},{k:"p",t:"9.5. Обработчик обеспечивает разграничение прав доступа к персональным данным и предоставляет доступ только лицам, которым он необходим для выполнения соответствующих технических или договорных обязанностей."},{k:"p",t:"9.6. Обработчик обеспечивает применение мер по выявлению и предотвращению несанкционированного доступа, регистрации значимых событий безопасности, резервному копированию и восстановлению информации в объеме, соответствующем характеру используемой информационной системы."},{k:"p",t:"9.7. Обработчик обязуется по запросу Оператора ПД в течение срока действия Поручения предоставлять документы или сведения, подтверждающие принятие мер, необходимых для выполнения требований законодательства Российской Федерации в отношении обработки персональных данных по настоящему Поручению."},{k:"p",t:"При предоставлении таких сведений Обработчик вправе исключать информацию, раскрытие которой способно создать угрозу безопасности информационной системы, нарушить права других пользователей или раскрыть охраняемую законом тайну."},{k:"p",t:"9.8. Обработчик не вправе:"},{k:"li",t:"продавать клиентскую базу Оператора ПД;"},{k:"li",t:"использовать ее для собственной рекламы;"},{k:"li",t:"формировать на ее основании собственную клиентскую базу;"},{k:"li",t:"связываться с клиентами Оператора ПД в собственных коммерческих целях;"},{k:"li",t:"использовать информацию для целей, не связанных с исполнением настоящего Поручения;"},{k:"li",t:"распространять персональные данные неопределенному кругу лиц без отдельного законного основания."},{k:"p",t:"9.9. Обязанность соблюдения конфиденциальности сохраняется после прекращения настоящего Поручения."},{k:"h",t:"10. Локализация персональных данных"},{k:"p",t:"10.1. При обработке персональных данных граждан Российской Федерации Обработчик соблюдает требования законодательства Российской Федерации о локализации персональных данных."},{k:"p",t:"10.2. Запись, систематизация, накопление, хранение, уточнение и извлечение персональных данных, собираемых с использованием сети Интернет, осуществляются с использованием баз данных, находящихся на территории Российской Федерации, за исключением случаев, прямо предусмотренных законодательством Российской Федерации."},{k:"p",t:"10.3. Обработчик учитывает требования локализации при выборе серверной, облачной и иной инфраструктуры для НЭК CRM."},{k:"h",t:"11. Привлечение поставщиков инфраструктуры и иных лиц"},{k:"p",t:"11.1. Оператор ПД предоставляет Обработчику право привлекать для исполнения настоящего Поручения поставщиков серверной, облачной, сетевой и иной информационно-технологической инфраструктуры, если такое привлечение необходимо для обеспечения работы НЭК CRM."},{k:"p",t:"11.2. Обработчик вправе привлекать таких лиц только в объеме, необходимом для выполнения соответствующих технических функций."},{k:"p",t:"11.3. При привлечении лиц, участвующих в обработке персональных данных, Обработчик обеспечивает возложение на них обязанностей по:"},{k:"li",t:"соблюдению конфиденциальности;"},{k:"li",t:"ограничению целей обработки;"},{k:"li",t:"обеспечению безопасности персональных данных;"},{k:"li",t:"предотвращению использования данных для собственных целей;"},{k:"li",t:"соблюдению применимых требований законодательства Российской Федерации."},{k:"p",t:"11.4. Привлечение поставщика инфраструктуры не означает предоставления ему права распоряжаться клиентской базой Оператора ПД или использовать ее в собственных целях."},{k:"p",t:"11.5. Обработчик несет перед Оператором ПД ответственность за соблюдение привлеченными им лицами условий обработки в пределах, предусмотренных договором и законодательством Российской Федерации."},{k:"h",t:"12. Трансграничная передача"},{k:"p",t:"12.1. Обработчик не осуществляет трансграничную передачу персональных данных, обрабатываемых по настоящему Поручению, без наличия соответствующего правового основания и выполнения требований законодательства Российской Федерации."},{k:"p",t:"12.2. Если для предоставления новой функции НЭК CRM возникнет необходимость в трансграничной передаче персональных данных, Обработчик до начала такой обработки обеспечивает выполнение применимых требований законодательства Российской Федерации и соответствующее договорное оформление."},{k:"p",t:"12.3. Если трансграничная передача требует изменения условий настоящего Поручения или совершения дополнительных действий со стороны Оператора ПД, Обработчик уведомляет Оператора ПД до начала использования соответствующей функции."},{k:"h",t:"13. Запросы субъектов персональных данных"},{k:"p",t:"13.1. Обязанность по взаимодействию с субъектом персональных данных в отношении клиентской базы Оператора ПД в первую очередь исполняется Оператором ПД."},{k:"p",t:"13.2. Если для выполнения законного требования субъекта требуется техническое действие со стороны Обработчика, Оператор ПД направляет Обработчику соответствующий запрос."},{k:"p",t:"13.3. Обработчик оказывает Оператору ПД разумно необходимое содействие, в том числе в:"},{k:"li",t:"поиске персональных данных;"},{k:"li",t:"выгрузке информации;"},{k:"li",t:"блокировании;"},{k:"li",t:"исправлении;"},{k:"li",t:"уточнении;"},{k:"li",t:"удалении;"},{k:"li",t:"уничтожении персональных данных."},{k:"p",t:"13.4. Обработчик исполняет такие запросы в срок, позволяющий Оператору ПД выполнить предусмотренные законодательством Российской Федерации обязанности, с учетом характера и технической сложности соответствующего действия."},{k:"p",t:"13.5. При обращении субъекта персональных данных непосредственно к Обработчику по вопросу данных, оператором которых является Пользователь НЭК CRM, Обработчик вправе сообщить субъекту о необходимости обращения к соответствующему Оператору ПД и при необходимости уведомить Оператора ПД о полученном обращении."},{k:"h",t:"14. Инциденты безопасности"},{k:"p",t:"14.1. При выявлении факта неправомерной или случайной передачи, предоставления, распространения либо доступа к персональным данным, обрабатываемым по настоящему Поручению, Обработчик принимает меры для ограничения последствий инцидента и предотвращения дальнейшего неправомерного доступа."},{k:"p",t:"14.2. Обработчик уведомляет Оператора ПД о соответствующем инциденте без неоправданной задержки, но не позднее 12 часов с момента его выявления, если инцидент затрагивает персональные данные, обрабатываемые по Поручению."},{k:"p",t:"14.3. Первичное уведомление при наличии соответствующей информации должно содержать:"},{k:"li",t:"описание характера инцидента;"},{k:"li",t:"дату и время его выявления;"},{k:"li",t:"предполагаемые причины;"},{k:"li",t:"категории затронутых данных;"},{k:"li",t:"известный или предполагаемый круг затронутых субъектов;"},{k:"li",t:"возможные последствия;"},{k:"li",t:"уже принятые меры;"},{k:"li",t:"контакт для взаимодействия по вопросам расследования."},{k:"p",t:"14.4. Обработчик проводит внутреннее расследование и предоставляет Оператору ПД дополнительную информацию о его результатах в разумный срок с учетом установленных законодательством сроков уведомления уполномоченного органа."},{k:"p",t:"14.5. Обработчик оказывает Оператору ПД необходимое содействие в подготовке сведений, которые Оператор ПД обязан предоставить уполномоченному органу в связи с соответствующим инцидентом."},{k:"p",t:"14.6. Стороны взаимодействуют добросовестно и своевременно предоставляют друг другу имеющуюся информацию, необходимую для установления причин и последствий инцидента."},{k:"h",t:"15. Уточнение, блокирование и прекращение неправомерной обработки"},{k:"p",t:"15.1. При получении от Оператора ПД законного требования об уточнении, блокировании или прекращении обработки персональных данных Обработчик выполняет необходимые действия в пределах своих технических возможностей и настоящего Поручения."},{k:"p",t:"15.2. В случае выявления неправомерной обработки Обработчик без неоправданной задержки принимает меры к ее прекращению и уведомляет Оператора ПД, если нарушение касается данных, переданных им на обработку."},{k:"p",t:"15.3. Если нарушение невозможно устранить без уничтожения соответствующих персональных данных, Обработчик обеспечивает их уничтожение на основании законного поручения Оператора ПД или в иных предусмотренных законодательством случаях."},{k:"h",t:"16. Резервное копирование"},{k:"p",t:"16.1. Обработчик вправе создавать резервные копии персональных данных исключительно для обеспечения сохранности, отказоустойчивости и возможности восстановления НЭК CRM."},{k:"p",t:"16.2. Резервные копии:"},{k:"li",t:"не используются для самостоятельных коммерческих целей;"},{k:"li",t:"защищаются от несанкционированного доступа;"},{k:"li",t:"хранятся ограниченный срок в соответствии с установленным циклом резервного копирования;"},{k:"li",t:"используются только для восстановления информации и обеспечения работоспособности Сервиса."},{k:"p",t:"16.3. После удаления персональных данных из основной информационной системы их копии могут сохраняться в резервных копиях до окончания соответствующего технологического цикла хранения."},{k:"p",t:"Если выборочное уничтожение данных в конкретной резервной копии технически невозможно, такие данные не должны использоваться для обычной деятельности и подлежат уничтожению по мере плановой ротации резервных копий в пределах сроков, допускаемых законодательством Российской Федерации."},{k:"h",t:"17. Прекращение Поручения и удаление данных"},{k:"p",t:"17.1. Настоящее Поручение действует в течение срока действия договора на использование НЭК CRM."},{k:"p",t:"17.2. До прекращения доступа к НЭК CRM Оператор ПД обязан самостоятельно сохранить или экспортировать необходимую ему информацию с использованием предусмотренных Сервисом функций."},{k:"p",t:"17.3. После прекращения договора Обработчик прекращает обработку персональных данных Оператора ПД, за исключением обработки, необходимой:"},{k:"li",t:"для исполнения законных требований Оператора ПД;"},{k:"li",t:"для завершения удаления информации;"},{k:"li",t:"для выполнения требований законодательства Российской Федерации;"},{k:"li",t:"для защиты законных прав сторон в пределах допускаемых законодательством сроков."},{k:"p",t:"17.4. При отсутствии иных законных оснований персональные данные удаляются из основной информационной системы в срок, не превышающий 30 дней с момента прекращения цели обработки или получения соответствующего законного требования."},{k:"p",t:"17.5. Если немедленное уничтожение отдельных копий технически невозможно, такие данные блокируются либо иным образом исключаются из обычной обработки и уничтожаются в ходе установленного технологического цикла, но не позднее предельных сроков, предусмотренных законодательством Российской Федерации."},{k:"p",t:"17.6. После прекращения Поручения Обработчик не вправе использовать сохраненные технические копии персональных данных для любых новых целей."},{k:"h",t:"18. Подтверждение выполнения требований"},{k:"p",t:"18.1. По обоснованному запросу Оператора ПД Обработчик предоставляет информацию, необходимую для подтверждения выполнения обязанностей, установленных настоящим Поручением и законодательством Российской Федерации."},{k:"p",t:"18.2. Обработчик вправе предоставить подтверждение в форме:"},{k:"li",t:"описания применяемых организационных мер;"},{k:"li",t:"описания технических мер без раскрытия критических параметров безопасности;"},{k:"li",t:"сведений об используемой инфраструктуре;"},{k:"li",t:"локальных документов или выписок из них;"},{k:"li",t:"результатов проверок или иных документов, которыми располагает Обработчик."},{k:"p",t:"18.3. Оператор ПД обязуется использовать полученную информацию исключительно для целей оценки соблюдения требований законодательства и не раскрывать сведения, составляющие коммерческую тайну Обработчика или способные снизить безопасность НЭК CRM."},{k:"h",t:"19. Ответственность сторон"},{k:"p",t:"19.1. Оператор ПД несет ответственность за:"},{k:"li",t:"законность получения персональных данных;"},{k:"li",t:"определение правомерных целей их обработки;"},{k:"li",t:"наличие необходимых правовых оснований;"},{k:"li",t:"получение необходимых согласий субъектов;"},{k:"li",t:"законность передачи персональных данных Обработчику;"},{k:"li",t:"соответствие состава данных целям обработки;"},{k:"li",t:"действия своих работников и иных пользователей учетных записей;"},{k:"li",t:"своевременность исполнения требований субъектов персональных данных."},{k:"p",t:"19.2. Обработчик несет перед Оператором ПД ответственность за обработку персональных данных в нарушение настоящего Поручения и применимых требований законодательства Российской Федерации в пределах, предусмотренных законом и договором."},{k:"p",t:"19.3. В отношениях с субъектами персональных данных распределение ответственности между Оператором ПД и Обработчиком определяется законодательством Российской Федерации."},{k:"p",t:"19.4. Ни одно положение настоящего Поручения не освобождает сторону от ответственности, которая не может быть ограничена или исключена соглашением сторон в соответствии с законодательством Российской Федерации."},{k:"h",t:"20. Конфиденциальность"},{k:"p",t:"20.1. Информация и персональные данные, к которым стороны получают доступ в связи с исполнением настоящего Поручения, являются конфиденциальными, если иное не предусмотрено законодательством Российской Федерации."},{k:"p",t:"20.2. Доступ к персональным данным предоставляется только лицам, которым такой доступ необходим для выполнения соответствующих обязанностей."},{k:"p",t:"20.3. Обработчик не получает каких-либо имущественных прав на клиентскую базу Оператора ПД в результате ее размещения в НЭК CRM."},{k:"p",t:"20.4. Прекращение договора не прекращает обязанности сторон по соблюдению конфиденциальности в отношении ранее полученной информации."},{k:"h",t:"21. Заключительные положения"},{k:"p",t:"21.1. Настоящее Поручение регулируется законодательством Российской Федерации."},{k:"p",t:"21.2. Поручение применяется исключительно к персональным данным, которые Оператор ПД обрабатывает с использованием НЭК CRM и в отношении которых НЭК CRM фактически осуществляет обработку по поручению Оператора ПД."},{k:"p",t:"21.3. В случае противоречия между настоящим Поручением и общими положениями Публичной оферты в вопросах обработки персональных данных по поручению применяются положения настоящего Поручения."},{k:"p",t:"21.4. Политика обработки персональных данных НЭК CRM применяется к отношениям сторон в той части, в которой она не противоречит настоящему Поручению и соответствует роли Обработчика в соответствующей операции."},{k:"p",t:"21.5. Актуальная редакция настоящего Поручения размещается на сайте НЭК CRM."},{k:"p",t:"21.6. Существенные изменения условий обработки персональных данных применяются с учетом требований законодательства Российской Федерации и условий Публичной оферты."},{k:"h",t:"22. Реквизиты Обработчика"},{k:"h",t:"Обработчик:"},{k:"p",t:"Индивидуальный предпринимательНеклюдов Артем Анатольевич"},{k:"p",t:"ИНН: 263221164126"},{k:"p",t:"ОГРНИП: 324265100105224"},{k:"p",t:"Электронная почта: SCRM@nakcrm.ru"},{k:"p",t:"Сайт: https://nakcrm.ru"},{k:"p",t:"Реквизиты Оператора ПД определяются на основании сведений, предоставленных им при регистрации, оформлении учетной записи, оплате Сервиса либо иным способом в соответствии с Публичной офертой."},{k:"p",t:"Настоящее Поручение заключается в электронной форме путем акцепта Публичной оферты и не требует составления отдельного экземпляра на бумажном носителе, если иное не предусмотрено соглашением сторон или законодательством Российской Федерации."}]},{slug:"personal-data-consent",title:"Согласие на обработку персональных данных",subtitle:"Согласие субъекта персональных данных",version:"",blocks:[{k:"h",t:"Согласие на обработку персональных данных"},{k:"p",t:"Настоящим я, действуя свободно, своей волей и в своем интересе, предоставляю индивидуальному предпринимателю Неклюдову Артему Анатольевичу (далее — Оператор) согласие на обработку моих персональных данных на условиях, изложенных в настоящем Согласии."},{k:"h",t:"Оператор:"},{k:"p",t:"Индивидуальный предприниматель Неклюдов Артем Анатольевич"},{k:"p",t:"ИНН: 263221164126"},{k:"p",t:"ОГРНИП: 324265100105224"},{k:"p",t:"Почтовый адрес: г. Реж, ул. Трудовая, д. 93/2, кв. 23"},{k:"p",t:"Адрес электронной почты: SCRM@nakcrm.ru"},{k:"p",t:"Сайт: https://nakcrm.ru"},{k:"p",t:"Сервис: НЭК CRM"},{k:"h",t:"1. Персональные данные, на обработку которых предоставляется согласие"},{k:"p",t:"В зависимости от используемых мной функций Сайта и НЭК CRM я предоставляю согласие на обработку следующих персональных данных:"},{k:"li",t:"фамилии, имени и отчества — при их предоставлении;"},{k:"li",t:"номера телефона;"},{k:"li",t:"адреса электронной почты;"},{k:"li",t:"сведений, указываемых при регистрации и создании учетной записи;"},{k:"li",t:"идентификатора учетной записи;"},{k:"li",t:"сведений об организации или сервисном центре, от имени или в интересах которого я использую НЭК CRM;"},{k:"li",t:"сведений о моей должности и роли в НЭК CRM — при их указании;"},{k:"li",t:"настроек учетной записи;"},{k:"li",t:"содержания моих обращений в службу поддержки и сведений, которые я самостоятельно предоставляю Оператору при таком обращении;"},{k:"li",t:"иных персональных данных, которые я самостоятельно предоставляю Оператору при использовании соответствующих форм Сайта и функций НЭК CRM и обработка которых необходима для указанных в настоящем Согласии целей."},{k:"p",t:"При использовании Сайта и НЭК CRM также могут обрабатываться технические сведения, связанные с использованием мной Сервиса, в том числе IP-адрес, сведения о браузере, операционной системе и устройстве, дата и время обращения к Сервису, идентификаторы учетной записи и сессии, сведения о технических событиях и ошибках."},{k:"p",t:"Настоящее Согласие не предусматривает целенаправленную обработку специальных категорий персональных данных или биометрических персональных данных с целью установления личности."},{k:"h",t:"2. Цели обработки персональных данных"},{k:"p",t:"Персональные данные могут обрабатываться Оператором в следующих целях:"},{k:"li",t:"регистрации и создания моей учетной записи в НЭК CRM;"},{k:"li",t:"идентификации и аутентификации при использовании Сервиса;"},{k:"li",t:"предоставления доступа к функциям НЭК CRM;"},{k:"li",t:"настройки и администрирования моей учетной записи;"},{k:"li",t:"организации взаимодействия с Оператором;"},{k:"li",t:"обработки моих обращений, запросов и сообщений;"},{k:"li",t:"предоставления технической и информационной поддержки;"},{k:"li",t:"направления сервисных уведомлений, связанных с учетной записью, безопасностью и использованием НЭК CRM;"},{k:"li",t:"обеспечения безопасности учетной записи и Сервиса;"},{k:"li",t:"предотвращения несанкционированного доступа, злоупотреблений и иных неправомерных действий;"},{k:"li",t:"диагностики технических ошибок и обеспечения стабильной работы НЭК CRM;"},{k:"li",t:"анализа и совершенствования работы Сайта и НЭК CRM в случаях, когда соответствующая обработка осуществляется на основании настоящего Согласия."},{k:"p",t:"Обработка персональных данных, необходимая для заключения и исполнения договора, выполнения требований законодательства Российской Федерации либо осуществляемая на ином предусмотренном законом основании, может осуществляться независимо от настоящего Согласия в пределах соответствующего правового основания."},{k:"h",t:"3. Действия с персональными данными"},{k:"p",t:"Я предоставляю Оператору согласие на совершение с моими персональными данными следующих действий:"},{k:"li",t:"сбор;"},{k:"li",t:"запись;"},{k:"li",t:"систематизация;"},{k:"li",t:"накопление;"},{k:"li",t:"хранение;"},{k:"li",t:"уточнение и обновление;"},{k:"li",t:"извлечение;"},{k:"li",t:"использование;"},{k:"li",t:"предоставление доступа лицам, привлекаемым Оператором к обработке персональных данных, в случаях и пределах, предусмотренных настоящим Согласием и законодательством Российской Федерации;"},{k:"li",t:"обезличивание;"},{k:"li",t:"блокирование;"},{k:"li",t:"удаление;"},{k:"li",t:"уничтожение."},{k:"p",t:"Оператор не получает на основании настоящего Согласия право распространять мои персональные данные неопределенному кругу лиц."},{k:"h",t:"4. Способы обработки"},{k:"p",t:"Обработка персональных данных может осуществляться:"},{k:"li",t:"с использованием средств автоматизации;"},{k:"li",t:"без использования средств автоматизации;"},{k:"li",t:"смешанным способом."},{k:"p",t:"Обработка осуществляется посредством информационных систем Оператора и используемой им информационно-технологической инфраструктуры в объеме, необходимом для заявленных целей."},{k:"h",t:"5. Обработка с использованием сторонней инфраструктуры"},{k:"p",t:"Я согласен с тем, что для технического обеспечения работы НЭК CRM Оператор может поручать обработку персональных данных лицам, предоставляющим серверную, облачную и иную информационно-технологическую инфраструктуру, при соблюдении требований законодательства Российской Федерации."},{k:"p",t:"Такие лица вправе осуществлять обработку персональных данных исключительно в пределах поручения Оператора и в объеме, необходимом для предоставления соответствующих технических услуг."},{k:"p",t:"Предоставление настоящего Согласия не предоставляет таким лицам право использовать персональные данные для собственных рекламных, маркетинговых или иных самостоятельных целей."},{k:"h",t:"6. Рекламные и маркетинговые сообщения"},{k:"p",t:"Настоящее Согласие не является согласием на получение рекламы и не предоставляет Оператору право направлять мне рекламные или маркетинговые сообщения в случаях, когда законодательством Российской Федерации требуется получение отдельного предварительного согласия."},{k:"p",t:"Согласие на получение рекламных и маркетинговых сообщений, если такие сообщения направляются Оператором, оформляется отдельно."},{k:"p",t:"Сервисные уведомления, необходимые для функционирования учетной записи, обеспечения безопасности, исполнения договора и предоставления НЭК CRM, не относятся к согласию на рекламную рассылку и направляются при наличии соответствующего правового основания."},{k:"h",t:"7. Персональные данные третьих лиц в НЭК CRM"},{k:"p",t:"Настоящее Согласие распространяется только на обработку моих персональных данных и само по себе не является правовым основанием для обработки персональных данных других физических лиц, которые могут быть внесены мной в НЭК CRM."},{k:"p",t:"При размещении в НЭК CRM персональных данных клиентов, работников, представителей, контрагентов или иных третьих лиц я обязан обеспечить наличие предусмотренного законодательством Российской Федерации правового основания для такой обработки."},{k:"p",t:"Обработка Оператором таких данных в рамках предоставления НЭК CRM осуществляется в соответствии с условиями договора, поручением Пользователя на обработку персональных данных, Политикой обработки персональных данных и законодательством Российской Федерации."},{k:"h",t:"8. Срок действия согласия"},{k:"p",t:"Настоящее Согласие действует с момента его предоставления до наступления одного из следующих событий:"},{k:"li",t:"достижения целей обработки персональных данных, для которых было предоставлено Согласие;"},{k:"li",t:"утраты необходимости в обработке персональных данных для соответствующих целей;"},{k:"li",t:"отзыва настоящего Согласия субъектом персональных данных;"},{k:"li",t:"наступления иного предусмотренного законодательством Российской Федерации основания для прекращения обработки."},{k:"p",t:"Прекращение действия настоящего Согласия не препятствует Оператору продолжить обработку отдельных персональных данных, если для такой обработки имеется иное правовое основание, предусмотренное законодательством Российской Федерации."},{k:"h",t:"9. Отзыв согласия"},{k:"p",t:"Я вправе в любой момент отозвать настоящее Согласие путем направления соответствующего обращения Оператору по адресу:"},{k:"h",t:"SCRM@nakcrm.ru"},{k:"p",t:"Обращение должно содержать сведения, позволяющие Оператору идентифицировать заявителя и определить учетную запись или персональные данные, в отношении которых отзывается Согласие."},{k:"p",t:"Оператор вправе запросить дополнительные сведения, необходимые для подтверждения личности заявителя, если без этого невозможно достоверно определить принадлежность соответствующих персональных данных."},{k:"p",t:"После получения отзыва Оператор прекращает обработку персональных данных, осуществляемую именно на основании настоящего Согласия, и при отсутствии иных законных оснований обеспечивает прекращение обработки и уничтожение персональных данных в сроки и порядке, предусмотренные законодательством Российской Федерации."},{k:"p",t:"Отзыв Согласия не влияет на правомерность обработки персональных данных, осуществленной до момента его отзыва."},{k:"h",t:"10. Последствия отказа или отзыва согласия"},{k:"p",t:"Предоставление настоящего Согласия является добровольным."},{k:"p",t:"В случаях, когда без обработки определенных персональных данных объективно невозможно предоставить соответствующую функцию НЭК CRM, отказ от их предоставления или отзыв Согласия может привести к невозможности использования такой функции."},{k:"p",t:"При этом отказ или отзыв настоящего Согласия не влияет на обработку персональных данных, осуществляемую на иных предусмотренных законодательством Российской Федерации правовых основаниях."},{k:"h",t:"11. Политика обработки персональных данных"},{k:"p",t:"Подробная информация о порядке и условиях обработки персональных данных, правах субъектов персональных данных и применяемых Оператором мерах защиты содержится в Политике обработки персональных данных, размещенной по адресу:"},{k:"h",t:"https://nakcrm.ru/documents/privacy"},{k:"p",t:"Я подтверждаю, что до предоставления настоящего Согласия мне была предоставлена возможность ознакомиться с указанной Политикой."},{k:"h",t:"12. Способ предоставления согласия"},{k:"p",t:"При использовании электронной формы настоящее Согласие предоставляется путем совершения отдельного подтверждающего действия в интерфейсе Сайта или НЭК CRM, например путем установки отдельного флажка (чекбокса) напротив текста о предоставлении согласия и последующего направления соответствующей формы."},{k:"p",t:"Такое действие является выражением моего свободного, конкретного, предметного, информированного, сознательного и однозначного согласия на обработку указанных в настоящем документе персональных данных."}]},{slug:"marketing-consent",title:"Согласие на рекламные и маркетинговые сообщения",subtitle:"Согласие на обработку персональных данных в целях их направления",version:"15 августа 2026 года",blocks:[{k:"h",t:"Согласие на получение рекламных и маркетинговых сообщений"},{k:"h",t:"и обработку персональных данных в целях их направления"},{k:"h",t:"Редакция от 15 августа 2026 года"},{k:"p",t:"Настоящим я, являясь Пользователем сайта и (или) сервиса НЭК CRM, действуя свободно, своей волей и в своем интересе, предоставляю индивидуальному предпринимателю Неклюдову Артему Анатольевичу согласие на получение рекламных и маркетинговых сообщений, а также на обработку моих персональных данных исключительно в целях направления таких сообщений на условиях настоящего Согласия."},{k:"p",t:"Предоставление настоящего Согласия является добровольным и не является обязательным условием регистрации, заключения договора, приобретения Тарифа или использования НЭК CRM."},{k:"h",t:"1. Сведения об Операторе"},{k:"h",t:"Индивидуальный предприниматель Неклюдов Артем Анатольевич"},{k:"p",t:"ИНН: 263221164126"},{k:"p",t:"ОГРНИП: 324265100105224"},{k:"p",t:"Электронная почта: SCRM@nakcrm.ru"},{k:"p",t:"Сайт: https://nakcrm.ru"},{k:"p",t:"Сервис: НЭК CRM"},{k:"p",t:"Далее — Оператор."},{k:"h",t:"2. Содержание рекламных и маркетинговых сообщений"},{k:"p",t:"2.1. На основании настоящего Согласия Оператор вправе направлять мне сообщения рекламного, информационно-рекламного и маркетингового характера, касающиеся НЭК CRM и предоставляемых Оператором продуктов и услуг."},{k:"p",t:"Такие сообщения могут содержать информацию:"},{k:"li",t:"о возможностях и функциональных возможностях НЭК CRM;"},{k:"li",t:"о выпуске новых функций и модулей;"},{k:"li",t:"о новых Тарифах и изменениях тарифных предложений;"},{k:"li",t:"о скидках, специальных предложениях и акциях;"},{k:"li",t:"о бонусах и льготных условиях использования Сервиса;"},{k:"li",t:"о специальных условиях приобретения или продления доступа;"},{k:"li",t:"о дополнительных услугах и интеграциях НЭК CRM;"},{k:"li",t:"о новых продуктах и сервисах Оператора;"},{k:"li",t:"о мероприятиях, вебинарах, презентациях и иных событиях, связанных с НЭК CRM;"},{k:"li",t:"о предложениях принять участие в опросах, исследованиях и мероприятиях, связанных с развитием продукта;"},{k:"li",t:"об иных предложениях Оператора, направленных на продвижение НЭК CRM и связанных с ним продуктов и услуг."},{k:"p",t:"2.2. Настоящее Согласие не предоставляет Оператору права направлять мне самостоятельную рекламу товаров или услуг третьих лиц, не связанную с НЭК CRM, если для этого отсутствует отдельное правовое основание или отдельное согласие."},{k:"h",t:"3. Каналы направления сообщений"},{k:"p",t:"3.1. Рекламные и маркетинговые сообщения могут направляться с использованием контактных данных и технических средств связи, предоставленных мной Оператору, в том числе посредством:"},{k:"li",t:"электронной почты;"},{k:"li",t:"SMS-сообщений;"},{k:"li",t:"сообщений в мессенджерах;"},{k:"li",t:"push-уведомлений;"},{k:"li",t:"уведомлений и сообщений в интерфейсе НЭК CRM;"},{k:"li",t:"телефонных звонков;"},{k:"li",t:"иных средств электросвязи, доступных Оператору и указанных мной в качестве способа связи."},{k:"p",t:"3.2. Оператор направляет сообщения только по тем каналам, использование которых технически возможно и для которых мной были предоставлены необходимые контактные данные."},{k:"p",t:"3.3. При наличии соответствующей функциональности я вправе самостоятельно выбирать или отключать отдельные каналы получения рекламных сообщений в настройках НЭК CRM."},{k:"h",t:"4. Персональные данные, используемые для рекламных и маркетинговых сообщений"},{k:"p",t:"4.1. В целях направления рекламных и маркетинговых сообщений Оператор вправе обрабатывать следующие мои персональные данные:"},{k:"li",t:"имя;"},{k:"li",t:"фамилию — при ее предоставлении;"},{k:"li",t:"отчество — при его предоставлении;"},{k:"li",t:"номер телефона;"},{k:"li",t:"адрес электронной почты;"},{k:"li",t:"идентификатор учетной записи НЭК CRM;"},{k:"li",t:"сведения о выбранном мною канале связи;"},{k:"li",t:"сведения о наличии или отсутствии настоящего Согласия;"},{k:"li",t:"сведения о дате, времени и способе предоставления или отзыва Согласия."},{k:"p",t:"4.2. Для подтверждения факта получения настоящего Согласия Оператор также вправе сохранять техническую информацию о его предоставлении, включая:"},{k:"li",t:"дату и время совершения подтверждающего действия;"},{k:"li",t:"идентификатор учетной записи;"},{k:"li",t:"версию настоящего Согласия;"},{k:"li",t:"страницу или форму, посредством которой было предоставлено Согласие;"},{k:"li",t:"IP-адрес, если он фиксируется информационной системой;"},{k:"li",t:"технический идентификатор сессии;"},{k:"li",t:"сведения о совершенном Пользователем подтверждающем действии."},{k:"p",t:"4.3. Указанная техническая информация используется в том числе для подтверждения факта, времени, содержания и способа предоставления или отзыва настоящего Согласия."},{k:"h",t:"5. Действия с персональными данными"},{k:"p",t:"5.1. В целях, предусмотренных настоящим Согласием, Оператор вправе осуществлять следующие действия с указанными персональными данными:"},{k:"li",t:"сбор;"},{k:"li",t:"запись;"},{k:"li",t:"систематизацию;"},{k:"li",t:"накопление;"},{k:"li",t:"хранение;"},{k:"li",t:"уточнение;"},{k:"li",t:"обновление;"},{k:"li",t:"извлечение;"},{k:"li",t:"использование;"},{k:"li",t:"предоставление доступа лицам, привлекаемым Оператором для технической отправки сообщений;"},{k:"li",t:"блокирование;"},{k:"li",t:"удаление;"},{k:"li",t:"уничтожение."},{k:"p",t:"5.2. Обработка может осуществляться с использованием средств автоматизации, без использования средств автоматизации или смешанным способом."},{k:"p",t:"5.3. Настоящее Согласие не предоставляет Оператору право распространять мои персональные данные неопределенному кругу лиц."},{k:"h",t:"6. Использование сервисов рассылки и связи"},{k:"p",t:"6.1. Для технического направления рекламных и маркетинговых сообщений Оператор вправе использовать услуги поставщиков:"},{k:"li",t:"электронной почты;"},{k:"li",t:"SMS-сообщений;"},{k:"li",t:"телефонии;"},{k:"li",t:"push-уведомлений;"},{k:"li",t:"мессенджеров;"},{k:"li",t:"иных информационно-технологических и коммуникационных сервисов."},{k:"p",t:"6.2. Если использование соответствующего сервиса предполагает обработку персональных данных другим лицом по поручению Оператора, такая обработка осуществляется в объеме, необходимом для направления соответствующего сообщения и исполнения технических функций."},{k:"p",t:"6.3. Привлечение технического поставщика не предоставляет такому лицу самостоятельного права использовать мои персональные данные для собственной рекламы или иных целей, не связанных с выполнением соответствующего поручения."},{k:"h",t:"7. Срок действия Согласия"},{k:"p",t:"7.1. Настоящее Согласие вступает в силу с момента совершения мной отдельного подтверждающего действия в интерфейсе Сайта или НЭК CRM."},{k:"p",t:"7.2. Согласие действует до момента его отзыва мной либо до прекращения Оператором соответствующей рекламной или маркетинговой деятельности."},{k:"p",t:"7.3. Прекращение использования НЭК CRM или расторжение договора само по себе не означает сохранения права Оператора на дальнейшее направление рекламных сообщений после отзыва настоящего Согласия."},{k:"h",t:"8. Отзыв Согласия и отказ от рекламы"},{k:"p",t:"8.1. Я вправе в любой момент отказаться от дальнейшего получения рекламных и маркетинговых сообщений полностью либо, при наличии соответствующей технической возможности, в отношении отдельного канала связи."},{k:"p",t:"8.2. Отказ может быть осуществлен:"},{k:"li",t:"посредством ссылки «Отписаться» или аналогичной ссылки в электронном сообщении;"},{k:"li",t:"посредством настроек уведомлений в НЭК CRM, если такая возможность предусмотрена;"},{k:"li",t:"путем направления требования на адрес электронной почты SCRM@nakcrm.ru;"},{k:"li",t:"иным предусмотренным Оператором способом, позволяющим выразить отказ от получения рекламы."},{k:"p",t:"8.3. В обращении по электронной почте рекомендуется указать номер телефона или адрес электронной почты, в отношении которого необходимо прекратить направление рекламных сообщений."},{k:"p",t:"8.4. После получения требования об отказе Оператор прекращает дальнейшее распространение рекламных и маркетинговых сообщений по соответствующему адресу или каналу связи."},{k:"p",t:"8.5. Отзыв настоящего Согласия не влияет на законность обработки и направления сообщений, осуществленных до момента получения Оператором отказа."},{k:"p",t:"8.6. После отказа Оператор вправе в пределах, допускаемых законодательством Российской Федерации, сохранить минимальный объем сведений о факте отказа, необходимый для предотвращения повторного направления рекламных сообщений лицу, отказавшемуся от их получения."},{k:"h",t:"9. Сервисные сообщения"},{k:"p",t:"9.1. Отказ от настоящего Согласия не означает отказ от получения сообщений, которые необходимы для исполнения договора, обеспечения работы НЭК CRM или безопасности учетной записи и не являются рекламными по своему содержанию."},{k:"p",t:"К таким сообщениям могут относиться:"},{k:"li",t:"уведомления о регистрации и состоянии учетной записи;"},{k:"li",t:"сообщения о входе в учетную запись и событиях безопасности;"},{k:"li",t:"сообщения, необходимые для восстановления доступа;"},{k:"li",t:"уведомления о технических работах;"},{k:"li",t:"сообщения о существенных изменениях в работе Сервиса;"},{k:"li",t:"сведения о платежах и состоянии оплаченного Тарифа;"},{k:"li",t:"уведомления об истечении оплаченного периода;"},{k:"li",t:"ответы службы поддержки;"},{k:"li",t:"юридически значимые уведомления, связанные с договорными отношениями;"},{k:"li",t:"иные сообщения, необходимые для предоставления НЭК CRM и исполнения обязательств Оператора."},{k:"p",t:"9.2. Если сообщение одновременно содержит сервисную и рекламную информацию, рекламная часть такого сообщения направляется только при наличии соответствующего согласия."},{k:"h",t:"10. Добровольность Согласия"},{k:"p",t:"10.1. Предоставление настоящего Согласия является добровольным."},{k:"p",t:"10.2. Отказ предоставить настоящее Согласие:"},{k:"li",t:"не препятствует регистрации в НЭК CRM;"},{k:"li",t:"не препятствует заключению договора;"},{k:"li",t:"не ограничивает доступ к оплаченному Тарифу;"},{k:"li",t:"не ухудшает основные функциональные возможности Сервиса;"},{k:"li",t:"не препятствует обращению в техническую поддержку."},{k:"p",t:"10.3. Оператор не вправе считать молчание, бездействие или отсутствие отказа согласием на получение рекламных сообщений."},{k:"h",t:"11. Соотношение с другими документами"},{k:"p",t:"11.1. Настоящее Согласие является самостоятельным документом и оформляется отдельно от:"},{k:"li",t:"Публичной оферты;"},{k:"li",t:"Политики обработки персональных данных;"},{k:"li",t:"Согласия на обработку персональных данных;"},{k:"li",t:"Поручения на обработку персональных данных;"},{k:"li",t:"иных документов, принимаемых или подтверждаемых Пользователем."},{k:"p",t:"11.2. Общие условия обработки и защиты персональных данных определяются Политикой обработки персональных данных, размещенной по адресу:"},{k:"h",t:"https://nakcrm.ru/documents/personal-data-policy"},{k:"p",t:"11.3. Основное согласие Пользователя на обработку его персональных данных размещается по адресу:"},{k:"h",t:"https://nakcrm.ru/documents/personal-data-consent"},{k:"p",t:"11.4. Настоящее Согласие регулирует исключительно обработку данных и направление сообщений в рекламных и маркетинговых целях."},{k:"p",t:"В части таких целей специальные условия настоящего Согласия применяются совместно с Политикой обработки персональных данных."},{k:"h",t:"12. Способ предоставления Согласия"},{k:"p",t:"12.1. Настоящее Согласие предоставляется путем совершения Пользователем отдельного однозначного подтверждающего действия."},{k:"p",t:"При использовании электронной формы таким действием является самостоятельная установка Пользователем отдельного флажка (чекбокса) напротив текста о согласии на получение рекламных и маркетинговых сообщений с последующим направлением соответствующей формы или подтверждением действия."},{k:"p",t:"12.2. Чекбокс не устанавливается заранее и требует самостоятельного действия Пользователя."},{k:"p",t:"12.3. Факт предоставления Согласия фиксируется информационной системой Оператора способом, позволяющим подтвердить:"},{k:"li",t:"лицо или учетную запись, предоставившие Согласие;"},{k:"li",t:"дату и время его предоставления;"},{k:"li",t:"содержание и редакцию Согласия;"},{k:"li",t:"способ его предоставления."},{k:"p",t:"12.4. Совершая указанное подтверждающее действие, я подтверждаю, что:"},{k:"li",t:"ознакомился с настоящим Согласием;"},{k:"li",t:"понимаю его содержание;"},{k:"li",t:"предоставляю Согласие добровольно;"},{k:"li",t:"понимаю возможность отказаться от рекламных сообщений в любое время."},{k:"h",t:"Оператор:"},{k:"p",t:"Индивидуальный предприниматель Неклюдов Артем АнатольевичИНН: 263221164126ОГРНИП: 324265100105224Email: SCRM@nakcrm.ruСайт: https://nakcrm.ru"},{k:"p",t:"Актуальная редакция настоящего Согласия размещается по адресу:"},{k:"h",t:"https://nakcrm.ru/documents/marketing-consent"}]},{slug:"privacy",title:"Политика обработки персональных данных",subtitle:"Политика оператора в отношении обработки персональных данных",version:"",blocks:[{k:"h",t:"Политика обработки персональных данных"},{k:"p",t:"Индивидуальный предприниматель Неклюдов Артем Анатольевич (далее — Оператор) осуществляет обработку персональных данных пользователей сайта и сервиса НЭК CRM в соответствии с законодательством Российской Федерации."},{k:"p",t:"Настоящая Политика определяет принципы, цели, правовые основания, условия и порядок обработки персональных данных, категории обрабатываемых данных и субъектов персональных данных, права субъектов, а также основные меры, принимаемые Оператором для защиты персональных данных."},{k:"p",t:"Перед предоставлением персональных данных рекомендуется ознакомиться с настоящей Политикой."},{k:"h",t:"1. Общие положения"},{k:"p",t:"1.1. Настоящая Политика разработана в соответствии с законодательством Российской Федерации, в том числе:"},{k:"li",t:"Федеральным законом от 27 июля 2006 г. № 152-ФЗ «О персональных данных»;"},{k:"li",t:"Федеральным законом от 27 июля 2006 г. № 149-ФЗ «Об информации, информационных технологиях и о защите информации»;"},{k:"li",t:"иными нормативными правовыми актами Российской Федерации, регулирующими обработку и защиту персональных данных."},{k:"p",t:"1.2. Для целей настоящей Политики используются следующие понятия:"},{k:"p",t:"Сайт — сайт Оператора, расположенный по адресу https://nakcrm.ru, включая его страницы и поддомены."},{k:"p",t:"НЭК CRM (Сервис) — предоставляемая Оператором информационная система для автоматизации деятельности сервисных центров и иных пользователей."},{k:"p",t:"Пользователь — физическое лицо, индивидуальный предприниматель, представитель организации, работник или иное лицо, использующее Сайт или Сервис."},{k:"p",t:"Субъект персональных данных — физическое лицо, к которому относятся обрабатываемые персональные данные."},{k:"p",t:"Остальные термины применяются в значении, установленном законодательством Российской Федерации."},{k:"p",t:"1.3. Настоящая Политика применяется к персональным данным, которые Оператор получает или обрабатывает при:"},{k:"li",t:"посещении Сайта;"},{k:"li",t:"регистрации и использовании НЭК CRM;"},{k:"li",t:"создании и использовании учетной записи;"},{k:"li",t:"обращении в службу поддержки;"},{k:"li",t:"заключении и исполнении договоров;"},{k:"li",t:"использовании отдельных функций Сервиса;"},{k:"li",t:"иных формах взаимодействия с Оператором, предполагающих обработку персональных данных."},{k:"p",t:"1.4. В отношении персональных данных Пользователей НЭК CRM Оператор самостоятельно определяет цели и условия обработки в пределах, предусмотренных настоящей Политикой и законодательством Российской Федерации."},{k:"p",t:"В отношении персональных данных клиентов, работников, представителей, контрагентов и иных физических лиц, самостоятельно размещаемых Пользователями в НЭК CRM, соответствующий Пользователь может выступать оператором персональных данных, а Оператор НЭК CRM — лицом, осуществляющим обработку персональных данных по поручению такого Пользователя."},{k:"p",t:"1.5. Обработка персональных данных осуществляется только при наличии правового основания, предусмотренного законодательством Российской Федерации."},{k:"p",t:"Если обработка осуществляется на основании согласия субъекта персональных данных, такое согласие предоставляется отдельно от иных документов и должно быть конкретным, предметным, информированным, сознательным и однозначным."},{k:"p",t:"Сам по себе факт посещения Сайта, использования НЭК CRM или ознакомления с настоящей Политикой не признается предоставлением согласия в случаях, когда законодательством Российской Федерации требуется получение отдельного согласия."},{k:"p",t:"1.6. Настоящая Политика является общедоступным документом и применяется совместно с Пользовательским соглашением, Публичной офертой, согласиями на обработку персональных данных и иными документами Оператора."},{k:"p",t:"В случае противоречия положений указанных документов требованиям законодательства Российской Федерации применяются требования законодательства Российской Федерации."},{k:"h",t:"2. Персональные данные, обрабатываемые Оператором"},{k:"p",t:"2.1. Под персональными данными понимается любая информация, относящаяся прямо или косвенно к определенному или определяемому физическому лицу."},{k:"p",t:"Состав обрабатываемых данных зависит от характера взаимодействия лица с НЭК CRM и используемых им функций."},{k:"p",t:"2.2. Данные Пользователей НЭК CRM"},{k:"p",t:"Оператор может обрабатывать:"},{k:"li",t:"фамилию, имя, отчество — при их предоставлении;"},{k:"li",t:"номер телефона;"},{k:"li",t:"адрес электронной почты;"},{k:"li",t:"сведения, указанные при регистрации и создании учетной записи;"},{k:"li",t:"идентификатор учетной записи;"},{k:"li",t:"сведения об организации или сервисном центре, к которому относится Пользователь;"},{k:"li",t:"должность, роль и права доступа в НЭК CRM;"},{k:"li",t:"сведения о выбранном тарифе, платежах и состоянии расчетов;"},{k:"li",t:"содержание обращений в службу поддержки и переписки с Оператором;"},{k:"li",t:"настройки учетной записи;"},{k:"li",t:"иные сведения, самостоятельно предоставленные Пользователем и необходимые для соответствующей функции Сервиса."},{k:"p",t:"Оператор не осуществляет целенаправленный сбор паспортных данных и иных данных документов, удостоверяющих личность, если их обработка не требуется для конкретной законной цели."},{k:"p",t:"2.3. Технические данные и файлы cookie"},{k:"p",t:"При посещении Сайта и использовании НЭК CRM Оператор может автоматически получать технические данные, включая:"},{k:"li",t:"IP-адрес;"},{k:"li",t:"сведения о браузере и операционной системе;"},{k:"li",t:"тип и характеристики устройства;"},{k:"li",t:"дату и время обращения к Сайту или Сервису;"},{k:"li",t:"сведения о действиях Пользователя в НЭК CRM;"},{k:"li",t:"технические идентификаторы учетной записи и сессии;"},{k:"li",t:"журналы событий и сведения о технических ошибках;"},{k:"li",t:"файлы cookie и содержащуюся в них информацию;"},{k:"li",t:"иные технические сведения, автоматически передаваемые устройством Пользователя."},{k:"p",t:"Файлы cookie могут использоваться для авторизации, поддержания пользовательской сессии, сохранения настроек, обеспечения безопасности и корректной работы Сайта и Сервиса."},{k:"p",t:"При наличии соответствующих функций отдельные cookie и аналогичные технологии могут использоваться для получения аналитической и статистической информации."},{k:"p",t:"Если для соответствующей обработки законодательством Российской Федерации требуется согласие субъекта персональных данных, обработка осуществляется после получения такого согласия."},{k:"p",t:"Пользователь может ограничить использование cookie средствами своего браузера. Отключение технически необходимых cookie может привести к невозможности использования отдельных функций НЭК CRM."},{k:"p",t:"2.4. Данные третьих лиц, размещаемые Пользователями в НЭК CRM"},{k:"p",t:"При использовании Сервиса Пользователь может самостоятельно размещать персональные данные своих клиентов, работников, представителей, контрагентов и иных физических лиц."},{k:"p",t:"Такие данные в зависимости от используемых функций могут включать:"},{k:"li",t:"фамилию, имя и отчество;"},{k:"li",t:"номер телефона;"},{k:"li",t:"адрес электронной почты;"},{k:"li",t:"адрес и иные контактные сведения;"},{k:"li",t:"сведения о заказах, заявках и обращениях;"},{k:"li",t:"сведения об устройстве, переданном для диагностики, обслуживания или ремонта, включая марку, модель, серийный номер, IMEI и иные идентификаторы;"},{k:"li",t:"сведения о запрошенных и выполненных работах;"},{k:"li",t:"историю взаимодействия с клиентом;"},{k:"li",t:"комментарии и примечания;"},{k:"li",t:"документы, изображения и иные материалы, загружаемые Пользователем;"},{k:"li",t:"иные сведения, самостоятельно внесенные Пользователем при использовании функциональных возможностей НЭК CRM."},{k:"p",t:"Пользователь обязан иметь предусмотренные законодательством основания для сбора, обработки и передачи Оператору таких персональных данных."},{k:"p",t:"Оператор обрабатывает указанные данные в пределах, необходимых для исполнения договора с Пользователем, его поручения и обеспечения работы соответствующих функций НЭК CRM."},{k:"p",t:"2.5. Специальные категории и биометрические персональные данные"},{k:"p",t:"НЭК CRM не предназначена для целенаправленного сбора специальных категорий персональных данных, касающихся расовой или национальной принадлежности, политических взглядов, религиозных или философских убеждений, состояния здоровья и интимной жизни."},{k:"p",t:"НЭК CRM также не предназначена для обработки биометрических персональных данных с целью установления личности человека."},{k:"p",t:"Пользователь не должен размещать такие данные в Сервисе без наличия предусмотренного законодательством Российской Федерации правового основания и объективной необходимости их обработки."},{k:"p",t:"2.6. Источники получения данных"},{k:"p",t:"Оператор получает персональные данные:"},{k:"li",t:"непосредственно от субъекта персональных данных;"},{k:"li",t:"автоматически при использовании Сайта и НЭК CRM;"},{k:"li",t:"от Пользователей НЭК CRM в отношении третьих лиц;"},{k:"li",t:"из иных законных источников в случаях, предусмотренных законодательством Российской Федерации."},{k:"h",t:"3. Цели обработки персональных данных"},{k:"p",t:"3.1. Данные Пользователей НЭК CRM обрабатываются в целях:"},{k:"li",t:"регистрации, создания и ведения учетной записи;"},{k:"li",t:"идентификации и аутентификации Пользователя;"},{k:"li",t:"предоставления доступа к функциям НЭК CRM;"},{k:"li",t:"создания и администрирования организаций, филиалов, учетных записей работников, ролей и прав доступа;"},{k:"li",t:"заключения, исполнения, изменения и прекращения договоров;"},{k:"li",t:"предоставления тарифов и управления подпиской;"},{k:"li",t:"учета платежей и взаиморасчетов;"},{k:"li",t:"формирования документов, связанных с предоставлением НЭК CRM;"},{k:"li",t:"оказания технической и информационной поддержки;"},{k:"li",t:"рассмотрения обращений, запросов, заявлений и претензий;"},{k:"li",t:"направления сервисных уведомлений;"},{k:"li",t:"обеспечения сохранности учетных записей и информации;"},{k:"li",t:"обеспечения информационной безопасности;"},{k:"li",t:"предотвращения несанкционированного доступа, мошенничества и злоупотреблений;"},{k:"li",t:"диагностики ошибок и обеспечения стабильной работы Сервиса;"},{k:"li",t:"анализа использования и совершенствования НЭК CRM;"},{k:"li",t:"защиты прав и законных интересов Оператора и Пользователей;"},{k:"li",t:"исполнения обязанностей, предусмотренных законодательством Российской Федерации;"},{k:"li",t:"направления рекламных и маркетинговых сообщений при наличии необходимого согласия."},{k:"p",t:"3.2. Данные, размещаемые Пользователями в НЭК CRM, могут обрабатываться по их поручению в целях:"},{k:"li",t:"ведения клиентской базы;"},{k:"li",t:"учета клиентов, заказов, заявок и ремонтов;"},{k:"li",t:"хранения истории взаимодействия с клиентами;"},{k:"li",t:"ведения сведений об устройствах, работах и комплектующих;"},{k:"li",t:"формирования актов, заказ-нарядов, гарантийных документов, квитанций и иных документов;"},{k:"li",t:"поиска, систематизации, изменения и отображения информации;"},{k:"li",t:"предоставления доступа уполномоченным Пользователем работникам;"},{k:"li",t:"формирования отчетов и статистики;"},{k:"li",t:"направления клиентам уведомлений по инициативе Пользователя;"},{k:"li",t:"импорта и экспорта данных;"},{k:"li",t:"резервного копирования и восстановления;"},{k:"li",t:"обеспечения сохранности и безопасности данных;"},{k:"li",t:"технического сопровождения Сервиса;"},{k:"li",t:"выполнения иных операций, необходимых для предоставления функциональных возможностей НЭК CRM и исполнения поручения Пользователя."},{k:"p",t:"Цели самостоятельного использования данных клиентов определяются Пользователем, выступающим оператором соответствующих персональных данных."},{k:"p",t:"Оператор НЭК CRM не использует такие данные для собственной рекламы, формирования самостоятельной клиентской базы, продажи информации или иных целей, не связанных с предоставлением Сервиса, исполнением поручения Пользователя либо требований законодательства."},{k:"p",t:"3.3. Сервисные и рекламные сообщения"},{k:"p",t:"Оператор может направлять Пользователю сообщения, необходимые для работы НЭК CRM и исполнения договора, включая уведомления:"},{k:"li",t:"о состоянии учетной записи;"},{k:"li",t:"о безопасности и входах в учетную запись;"},{k:"li",t:"о работе и доступности Сервиса;"},{k:"li",t:"о платежах и тарифе;"},{k:"li",t:"об истечении оплаченного периода;"},{k:"li",t:"об изменении документов и условий использования;"},{k:"li",t:"по результатам обращения Пользователя."},{k:"p",t:"Рекламные и маркетинговые сообщения направляются только при наличии необходимого предварительного согласия."},{k:"p",t:"Пользователь вправе отказаться от рекламных и маркетинговых сообщений предусмотренным Оператором способом."},{k:"p",t:"3.4. Аналитика и обезличивание"},{k:"p",t:"Оператор вправе использовать информацию об использовании НЭК CRM для анализа работы, выявления технических проблем, совершенствования функций и планирования развития Сервиса."},{k:"p",t:"При использовании персональных данных в статистических или исследовательских целях их обезличивание осуществляется в случаях, предусмотренных законодательством Российской Федерации."},{k:"h",t:"4. Правовые основания, порядок и сроки обработки персональных данных"},{k:"p",t:"4.1. Правовые основания обработки"},{k:"p",t:"В зависимости от цели обработка персональных данных осуществляется на основании:"},{k:"li",t:"согласия субъекта персональных данных;"},{k:"li",t:"необходимости заключения или исполнения договора, стороной которого, выгодоприобретателем или поручителем по которому является субъект персональных данных;"},{k:"li",t:"необходимости выполнения обязанностей Оператора, установленных законодательством Российской Федерации;"},{k:"li",t:"необходимости осуществления прав и законных интересов Оператора или третьих лиц при условии, что при этом не нарушаются права и свободы субъекта персональных данных;"},{k:"li",t:"поручения Пользователя на обработку персональных данных;"},{k:"li",t:"иных оснований, предусмотренных законодательством Российской Федерации."},{k:"p",t:"4.2. Действия и способы обработки"},{k:"p",t:"Оператор в зависимости от цели обработки может осуществлять следующие действия с персональными данными:"},{k:"li",t:"сбор;"},{k:"li",t:"запись;"},{k:"li",t:"систематизацию;"},{k:"li",t:"накопление;"},{k:"li",t:"хранение;"},{k:"li",t:"уточнение и обновление;"},{k:"li",t:"извлечение;"},{k:"li",t:"использование;"},{k:"li",t:"предоставление доступа в предусмотренных настоящей Политикой случаях;"},{k:"li",t:"обезличивание;"},{k:"li",t:"блокирование;"},{k:"li",t:"удаление;"},{k:"li",t:"уничтожение."},{k:"p",t:"Обработка преимущественно осуществляется с использованием средств автоматизации."},{k:"p",t:"В необходимых случаях отдельные операции могут выполняться без использования средств автоматизации."},{k:"p",t:"Оператор не осуществляет распространение персональных данных неопределенному кругу лиц без предусмотренного законодательством Российской Федерации основания."},{k:"p",t:"4.3. Сроки обработки и хранения"},{k:"p",t:"Персональные данные хранятся не дольше, чем этого требуют цели обработки, если иной срок хранения не предусмотрен законодательством Российской Федерации, договором или иным законным основанием."},{k:"p",t:"Срок обработки данных Пользователя может определяться сроком действия его учетной записи, договора с Оператором и периодом, необходимым для исполнения обязанностей сторон после прекращения договора."},{k:"p",t:"Персональные данные, которые должны сохраняться в силу требований законодательства Российской Федерации, хранятся в течение установленных законодательством сроков."},{k:"p",t:"Данные третьих лиц, размещенные Пользователем в НЭК CRM и обрабатываемые по его поручению, обрабатываются в течение срока действия соответствующего договора или поручения, а также в течение иных предусмотренных договором или законодательством сроков."},{k:"p",t:"4.4. Локализация данных"},{k:"p",t:"При сборе персональных данных граждан Российской Федерации с использованием сети Интернет Оператор обеспечивает запись, систематизацию, накопление, хранение, уточнение и извлечение таких персональных данных с использованием баз данных, находящихся на территории Российской Федерации, за исключением предусмотренных законом случаев."},{k:"p",t:"4.5. Прекращение обработки и уничтожение"},{k:"p",t:"Обработка персональных данных прекращается при:"},{k:"li",t:"достижении целей обработки;"},{k:"li",t:"утрате необходимости в достижении соответствующих целей;"},{k:"li",t:"прекращении договора, если отсутствуют основания для дальнейшего хранения данных;"},{k:"li",t:"отзыве согласия, когда отсутствуют иные законные основания обработки;"},{k:"li",t:"поступлении законного требования субъекта о прекращении обработки;"},{k:"li",t:"выявлении неправомерной обработки;"},{k:"li",t:"наступлении иных предусмотренных законодательством оснований."},{k:"p",t:"Персональные данные уничтожаются либо обезличиваются в порядке и сроки, предусмотренные законодательством Российской Федерации, если отсутствует законное основание для дальнейшей обработки."},{k:"p",t:"При невозможности немедленного уничтожения персональных данных Оператор осуществляет их блокирование и обеспечивает последующее уничтожение в установленный законодательством срок."},{k:"p",t:"4.6. Обработка по поручению"},{k:"p",t:"Если Оператор поручает обработку персональных данных другому лицу, соответствующее поручение оформляется в порядке, установленном законодательством Российской Федерации."},{k:"p",t:"Если Оператор НЭК CRM осуществляет обработку данных по поручению Пользователя, условия такого поручения устанавливаются договором между Оператором и Пользователем либо иным являющимся его частью документом."},{k:"h",t:"5. Предоставление персональных данных третьим лицам"},{k:"p",t:"5.1. Оператор не продает и не предоставляет персональные данные третьим лицам для их самостоятельного использования, кроме случаев, предусмотренных настоящей Политикой или законодательством Российской Федерации."},{k:"p",t:"5.2. Для размещения и обеспечения работы НЭК CRM Оператор вправе использовать услуги поставщиков серверной, облачной и иной информационно-технологической инфраструктуры."},{k:"p",t:"Если такой поставщик участвует в обработке персональных данных, его доступ и операции с данными ограничиваются объемом, необходимым для предоставления соответствующих услуг."},{k:"p",t:"В отношениях с такими лицами Оператор устанавливает требования к конфиденциальности, безопасности и защите персональных данных в случаях, когда это требуется законодательством Российской Федерации."},{k:"p",t:"5.3. Оператор вправе предоставлять персональные данные судам, правоохранительным, налоговым, надзорным и иным государственным органам при наличии предусмотренного законом основания и только в необходимом объеме."},{k:"p",t:"5.4. Доступ работников, подрядчиков и поставщиков инфраструктуры к персональным данным предоставляется только в пределах, необходимых для выполнения соответствующих функций."},{k:"p",t:"Такие лица не вправе использовать полученные персональные данные для собственных рекламных или иных самостоятельных целей без отдельного правового основания."},{k:"p",t:"5.5. Информация о лицах, которым поручена обработка персональных данных или которым персональные данные могут быть раскрыты на предусмотренном законом основании, предоставляется субъекту персональных данных в случаях и порядке, установленных законодательством Российской Федерации."},{k:"h",t:"6. Права субъектов персональных данных"},{k:"p",t:"6.1. Субъект персональных данных вправе:"},{k:"li",t:"получать информацию об обработке своих персональных данных;"},{k:"li",t:"получать подтверждение факта такой обработки;"},{k:"li",t:"получать доступ к обрабатываемым персональным данным;"},{k:"li",t:"получать сведения о целях, правовых основаниях, способах и сроках обработки;"},{k:"li",t:"требовать уточнения неполных, устаревших или неточных данных;"},{k:"li",t:"требовать блокирования персональных данных в предусмотренных законом случаях;"},{k:"li",t:"требовать уничтожения незаконно полученных или не необходимых для заявленной цели данных;"},{k:"li",t:"отозвать ранее предоставленное согласие;"},{k:"li",t:"требовать прекращения обработки в предусмотренных законодательством случаях;"},{k:"li",t:"отказаться от обработки в целях направления рекламных и маркетинговых сообщений;"},{k:"li",t:"обжаловать действия или бездействие Оператора в Роскомнадзор или в судебном порядке;"},{k:"li",t:"осуществлять иные права, предусмотренные законодательством Российской Федерации."},{k:"p",t:"6.2. Отзыв согласия"},{k:"p",t:"Отзыв согласия не во всех случаях означает немедленное прекращение обработки всех персональных данных."},{k:"p",t:"Если после отзыва согласия существуют иные законные основания обработки, Оператор вправе продолжить обработку в объеме и в течение срока, необходимых для соответствующего основания."},{k:"p",t:"При отсутствии иных оснований обработка прекращается, а персональные данные уничтожаются в установленном законодательством порядке."},{k:"p",t:"6.3. Обращение к Оператору"},{k:"p",t:"Для реализации своих прав субъект персональных данных или его представитель может обратиться к Оператору по адресу электронной почты:"},{k:"p",t:"SCRM@nakcrm.ru"},{k:"p",t:"Запрос должен содержать сведения, позволяющие идентифицировать заявителя и определить, в отношении каких персональных данных направлено обращение."},{k:"p",t:"Если законодательством Российской Федерации установлены специальные требования к форме или содержанию запроса, запрос должен соответствовать таким требованиям."},{k:"p",t:"Оператор вправе запросить дополнительные сведения, необходимые для достоверной идентификации заявителя или подтверждения полномочий представителя."},{k:"p",t:"6.4. Сроки рассмотрения"},{k:"p",t:"Информация, касающаяся обработки персональных данных, предоставляется субъекту или его представителю в течение десяти рабочих дней с момента обращения или получения соответствующего запроса."},{k:"p",t:"В предусмотренных законодательством случаях указанный срок может быть продлен не более чем на пять рабочих дней при направлении заявителю мотивированного уведомления."},{k:"p",t:"Уточнение, блокирование, прекращение обработки и уничтожение персональных данных осуществляются в порядке и сроки, предусмотренные законодательством Российской Федерации."},{k:"p",t:"6.5. Данные клиентов Пользователей НЭК CRM"},{k:"p",t:"Если обращение касается персональных данных, самостоятельно размещенных в НЭК CRM Пользователем, выступающим оператором таких данных, основные обязанности по реализации прав субъекта возлагаются на соответствующего Пользователя."},{k:"p",t:"Оператор НЭК CRM в пределах полученного поручения оказывает Пользователю необходимое содействие в поиске, выгрузке, уточнении, блокировании или удалении соответствующих данных средствами Сервиса."},{k:"h",t:"7. Защита персональных данных"},{k:"p",t:"7.1. Общие положения"},{k:"p",t:"Оператор принимает необходимые правовые, организационные и технические меры для защиты персональных данных от неправомерного или случайного доступа, уничтожения, изменения, блокирования, копирования, предоставления, распространения и иных неправомерных действий."},{k:"p",t:"Состав применяемых мер определяется с учетом характера и объема данных, способов обработки, архитектуры информационной системы, актуальных угроз и требований законодательства Российской Федерации."},{k:"p",t:"7.2. Организационные меры"},{k:"p",t:"Оператор применяет организационные меры, направленные в том числе на:"},{k:"li",t:"установление правил обработки и защиты персональных данных;"},{k:"li",t:"разграничение прав доступа;"},{k:"li",t:"предоставление доступа только в необходимом объеме;"},{k:"li",t:"установление порядка предоставления и прекращения прав доступа;"},{k:"li",t:"обеспечение конфиденциальности;"},{k:"li",t:"контроль действий лиц, имеющих доступ к данным;"},{k:"li",t:"выявление и расследование инцидентов;"},{k:"li",t:"внутренний контроль соблюдения правил обработки;"},{k:"li",t:"ознакомление лиц, работающих с персональными данными, с применимыми требованиями."},{k:"p",t:"7.3. Технические меры"},{k:"p",t:"С учетом архитектуры НЭК CRM Оператор применяет необходимые технические меры, включая:"},{k:"li",t:"идентификацию и аутентификацию пользователей;"},{k:"li",t:"разграничение доступа к данным и функциям;"},{k:"li",t:"использование защищенных протоколов передачи данных;"},{k:"li",t:"ограничение доступа к серверной и сетевой инфраструктуре;"},{k:"li",t:"регистрацию и анализ значимых событий информационной безопасности;"},{k:"li",t:"выявление признаков несанкционированного доступа;"},{k:"li",t:"своевременное обновление программного обеспечения;"},{k:"li",t:"устранение выявленных уязвимостей;"},{k:"li",t:"резервное копирование и восстановление информации;"},{k:"li",t:"защиту административных учетных записей;"},{k:"li",t:"контроль эффективности применяемых средств защиты."},{k:"p",t:"Конкретная техническая конфигурация средств защиты может изменяться без внесения изменений в настоящую Политику при условии соблюдения требований законодательства Российской Федерации."},{k:"p",t:"7.4. Сторонняя инфраструктура"},{k:"p",t:"При использовании арендованной серверной, облачной или иной инфраструктуры Оператор учитывает условия обработки информации и применяемые поставщиком меры безопасности."},{k:"p",t:"Возможность доступа поставщика инфраструктуры к персональным данным ограничивается целями и объемом, необходимыми для предоставления соответствующих услуг."},{k:"p",t:"7.5. Реагирование на инциденты"},{k:"p",t:"При выявлении инцидента, связанного с безопасностью персональных данных, Оператор принимает меры для:"},{k:"li",t:"прекращения несанкционированного доступа;"},{k:"li",t:"ограничения последствий инцидента;"},{k:"li",t:"определения затронутых данных;"},{k:"li",t:"устранения причин инцидента;"},{k:"li",t:"восстановления информации при необходимости;"},{k:"li",t:"проведения внутреннего расследования;"},{k:"li",t:"предотвращения повторения аналогичных событий."},{k:"p",t:"При установлении факта неправомерной или случайной передачи, предоставления, распространения либо доступа к персональным данным, повлекшего нарушение прав субъектов персональных данных, Оператор уведомляет уполномоченный орган в порядке и сроки, предусмотренные законодательством Российской Федерации, включая первоначальное уведомление в течение 24 часов и предоставление результатов внутреннего расследования в течение 72 часов."},{k:"h",t:"8. Изменение Политики"},{k:"p",t:"8.1. Оператор вправе изменять настоящую Политику в связи с изменением законодательства, функциональных возможностей НЭК CRM, состава и способов обработки персональных данных или иных обстоятельств, влияющих на содержание Политики."},{k:"p",t:"8.2. Актуальная редакция Политики размещается в свободном доступе по адресу:"},{k:"p",t:"https://nakcrm.ru/documents/privacy"},{k:"p",t:"Новая редакция вступает в силу с момента ее размещения, если в ней не установлен иной срок."},{k:"p",t:"8.3. При внесении существенных изменений, затрагивающих порядок обработки персональных данных или права субъектов, Оператор может дополнительно уведомить Пользователей посредством интерфейса НЭК CRM, электронной почты или иным доступным способом."},{k:"p",t:"Если изменение характера обработки требует получения нового согласия, такая обработка начинается после получения соответствующего согласия."},{k:"p",t:"8.4. Предыдущие редакции Политики могут сохраняться Оператором в архиве."},{k:"h",t:"9. Контактная информация Оператора"},{k:"p",t:"Оператор персональных данных:"},{k:"p",t:"Индивидуальный предприниматель Неклюдов Артем Анатольевич"},{k:"p",t:"ИНН: 263221164126"},{k:"p",t:"ОГРНИП: 324265100105224"},{k:"p",t:"Почтовый адрес для обращений: SCRM@nakcrm.ru"},{k:"p",t:"Электронная почта по вопросам обработки персональных данных: SCRM@nakcrm.ru"},{k:"p",t:"Сайт: https://nakcrm.ru"},{k:"p",t:"Обращения, связанные с получением информации об обработке персональных данных, их уточнением, блокированием, прекращением обработки, уничтожением, отзывом согласия и реализацией иных предусмотренных законодательством прав, могут направляться по указанным контактным данным."}]}],l=t=>i.find(k=>k.slug===t);export{i as L,l as g};
